import React, { useState } from 'react';

interface Question {
  id: string; subject: string; topic: string; year: string;
  question: string; options: string[]; answer: number; explanation: string;
}

const questions: Question[] = [
  {id:"ap001",subject:"Anatomy & Physiology",topic:"Cell Biology",year:"Year 1",question:"Which organelle is responsible for ATP production in the cell?",options:["Nucleus", "Mitochondria", "Ribosome", "Golgi apparatus"],answer:1,explanation:"Mitochondria are the powerhouses of the cell, producing ATP through cellular respiration."},
  {id:"ap002",subject:"Anatomy & Physiology",topic:"Cell Biology",year:"Year 1",question:"The process by which a cell engulfs large particles is called:",options:["Pinocytosis", "Phagocytosis", "Exocytosis", "Osmosis"],answer:1,explanation:"Phagocytosis involves the cell engulfing large particles like bacteria."},
  {id:"ap003",subject:"Anatomy & Physiology",topic:"Cardiovascular",year:"Year 1",question:"The normal adult heart rate at rest is:",options:["40-60 bpm", "60-100 bpm", "100-120 bpm", "120-150 bpm"],answer:1,explanation:"Normal resting heart rate for adults is 60-100 beats per minute."},
  {id:"ap004",subject:"Anatomy & Physiology",topic:"Cardiovascular",year:"Year 1",question:"Which chamber of the heart pumps oxygenated blood to the entire body?",options:["Right atrium", "Right ventricle", "Left atrium", "Left ventricle"],answer:3,explanation:"The left ventricle pumps oxygenated blood into the aorta and out to the systemic circulation."},
  {id:"ap005",subject:"Anatomy & Physiology",topic:"Respiratory",year:"Year 1",question:"The primary muscle of respiration is the:",options:["Intercostal muscle", "Diaphragm", "Sternocleidomastoid", "Trapezius"],answer:1,explanation:"The diaphragm is the main muscle driving normal inspiration."},
  {id:"ap006",subject:"Anatomy & Physiology",topic:"Respiratory",year:"Year 1",question:"Normal tidal volume in an adult at rest is approximately:",options:["150 ml", "500 ml", "1200 ml", "4800 ml"],answer:1,explanation:"Tidal volume (volume per normal breath) is approximately 500 ml in a resting adult."},
  {id:"ap007",subject:"Anatomy & Physiology",topic:"Renal",year:"Year 2",question:"The functional unit of the kidney is called:",options:["Glomerulus", "Nephron", "Loop of Henle", "Bowman capsule"],answer:1,explanation:"The nephron is the functional unit of the kidney responsible for filtration, reabsorption and secretion."},
  {id:"ap008",subject:"Anatomy & Physiology",topic:"Renal",year:"Year 2",question:"Normal urine output in an adult is approximately:",options:["100-200 ml/day", "500-700 ml/day", "1000-2000 ml/day", "3000-4000 ml/day"],answer:2,explanation:"Normal urine output is 1000-2000 ml/day; below 400 ml/day is oliguria."},
  {id:"ap009",subject:"Anatomy & Physiology",topic:"Nervous System",year:"Year 2",question:"The myelin sheath around nerve fibres is produced by:",options:["Astrocytes", "Schwann cells", "Microglia", "Oligodendrocytes"],answer:1,explanation:"Schwann cells form the myelin sheath around peripheral nerve fibres, speeding impulse conduction."},
  {id:"ap010",subject:"Anatomy & Physiology",topic:"Nervous System",year:"Year 2",question:"The autonomic nervous system is divided into sympathetic and:",options:["Somatic", "Parasympathetic", "Central", "Peripheral"],answer:1,explanation:"The ANS has two divisions: sympathetic (fight-or-flight) and parasympathetic (rest-and-digest)."},
  {id:"ap011",subject:"Anatomy & Physiology",topic:"Digestive",year:"Year 1",question:"Digestion of proteins begins in the:",options:["Mouth", "Oesophagus", "Stomach", "Small intestine"],answer:2,explanation:"Protein digestion begins in the stomach where pepsin (activated by HCl) breaks down proteins."},
  {id:"ap012",subject:"Anatomy & Physiology",topic:"Digestive",year:"Year 1",question:"Bile is produced by the liver and stored in the:",options:["Pancreas", "Duodenum", "Gallbladder", "Spleen"],answer:2,explanation:"Bile is produced by hepatocytes in the liver and stored and concentrated in the gallbladder."},
  {id:"ap013",subject:"Anatomy & Physiology",topic:"Endocrine",year:"Year 2",question:"Insulin is secreted by which cells of the pancreas?",options:["Alpha cells", "Beta cells", "Delta cells", "Acinar cells"],answer:1,explanation:"Beta cells of the islets of Langerhans secrete insulin in response to elevated blood glucose."},
  {id:"ap014",subject:"Anatomy & Physiology",topic:"Endocrine",year:"Year 2",question:"Which hormone is responsible for regulating calcium levels in the blood?",options:["Thyroxine", "Parathyroid hormone", "Cortisol", "Aldosterone"],answer:1,explanation:"Parathyroid hormone (PTH) raises blood calcium by promoting bone resorption and renal reabsorption."},
  {id:"ap015",subject:"Anatomy & Physiology",topic:"Blood",year:"Year 1",question:"The normal haemoglobin level for an adult male is approximately:",options:["8-10 g/dl", "11-13 g/dl", "13.5-17.5 g/dl", "18-22 g/dl"],answer:2,explanation:"Normal haemoglobin for adult males is 13.5-17.5 g/dl; for females it is 12-16 g/dl."},
  {id:"ap016",subject:"Anatomy & Physiology",topic:"Blood",year:"Year 1",question:"Which blood cells are primarily responsible for fighting infection?",options:["Erythrocytes", "Leucocytes", "Thrombocytes", "Reticulocytes"],answer:1,explanation:"Leucocytes (white blood cells) are the primary immune cells defending the body against infection."},
  {id:"ap017",subject:"Anatomy & Physiology",topic:"Musculoskeletal",year:"Year 2",question:"The type of bone cell responsible for bone resorption is the:",options:["Osteoblast", "Osteocyte", "Osteoclast", "Chondrocyte"],answer:2,explanation:"Osteoclasts break down bone matrix during bone resorption; osteoblasts build new bone."},
  {id:"ap018",subject:"Anatomy & Physiology",topic:"Musculoskeletal",year:"Year 2",question:"A sarcomere is the basic contractile unit of:",options:["Cardiac muscle only", "Smooth muscle", "Skeletal muscle", "Both cardiac and skeletal muscle"],answer:3,explanation:"Sarcomeres are the basic contractile units of both skeletal and cardiac muscle fibres."},
  {id:"ap019",subject:"Anatomy & Physiology",topic:"Reproductive",year:"Year 2",question:"The site of fertilisation in the female reproductive tract is typically the:",options:["Uterus", "Cervix", "Fallopian tube", "Ovary"],answer:2,explanation:"Fertilisation most commonly occurs in the ampulla of the fallopian (uterine) tube."},
  {id:"ap020",subject:"Anatomy & Physiology",topic:"Reproductive",year:"Year 2",question:"Progesterone is mainly produced by the:",options:["Anterior pituitary", "Adrenal cortex", "Corpus luteum", "Placenta"],answer:2,explanation:"After ovulation the corpus luteum secretes progesterone to maintain the endometrium."},
  {id:"ap021",subject:"Anatomy & Physiology",topic:"Skin",year:"Year 1",question:"The deepest layer of the epidermis is the:",options:["Stratum corneum", "Stratum lucidum", "Stratum granulosum", "Stratum basale"],answer:3,explanation:"The stratum basale is the deepest epidermal layer where mitosis produces new keratinocytes."},
  {id:"ap022",subject:"Anatomy & Physiology",topic:"Cardiovascular",year:"Year 1",question:"Normal adult systolic blood pressure is classified as:",options:["Below 90 mmHg", "90-100 mmHg", "Less than 120 mmHg", "140 mmHg or above is hypertension"],answer:2,explanation:"Normal systolic BP is less than 120 mmHg; 130+ is Stage 1 hypertension."},
  {id:"ap023",subject:"Anatomy & Physiology",topic:"Lymphatics",year:"Year 2",question:"The largest lymphatic vessel that drains into the left subclavian vein is the:",options:["Right lymphatic duct", "Cisterna chyli", "Thoracic duct", "Jugular trunk"],answer:2,explanation:"The thoracic duct is the largest lymphatic vessel, collecting lymph from most of the body."},
  {id:"ap024",subject:"Anatomy & Physiology",topic:"Nervous System",year:"Year 2",question:"The blood-brain barrier is primarily formed by:",options:["Choroid plexus", "Tight junctions and astrocyte end-feet", "Microglia", "Meninges"],answer:1,explanation:"The BBB is formed by tight junctions between endothelial cells of cerebral capillaries, supported by astrocyte end-feet."},
  {id:"ap025",subject:"Anatomy & Physiology",topic:"Respiratory",year:"Year 2",question:"Oxygen is transported in the blood primarily bound to:",options:["Plasma proteins", "Haemoglobin", "Myoglobin", "Dissolved in plasma"],answer:1,explanation:"About 98% of oxygen in blood is transported bound to haemoglobin in red blood cells."},
  {id:"ap026",subject:"Anatomy & Physiology",topic:"Fluid Balance",year:"Year 2",question:"The most abundant cation in extracellular fluid is:",options:["Potassium K+", "Calcium Ca2+", "Sodium Na+", "Magnesium Mg2+"],answer:2,explanation:"Sodium (Na+) is the principal extracellular cation and plays a key role in maintaining osmolality."},
  {id:"ap027",subject:"Anatomy & Physiology",topic:"Digestive",year:"Year 1",question:"Which enzyme breaks down starch in the mouth?",options:["Pepsin", "Salivary amylase", "Lipase", "Trypsin"],answer:1,explanation:"Salivary amylase (ptyalin) begins carbohydrate digestion in the mouth by breaking starch into maltose."},
  {id:"ap028",subject:"Anatomy & Physiology",topic:"Renal",year:"Year 2",question:"Filtration in the kidney occurs at the:",options:["Loop of Henle", "Collecting duct", "Glomerulus", "Proximal convoluted tubule"],answer:2,explanation:"Blood is filtered under pressure at the glomerulus, producing filtrate that enters Bowman's capsule."},
  {id:"ap029",subject:"Anatomy & Physiology",topic:"Cardiovascular",year:"Year 1",question:"The sinoatrial (SA) node is located in the:",options:["Left ventricle", "Interventricular septum", "Right atrium", "AV node region"],answer:2,explanation:"The SA node, the heart's primary pacemaker, is located in the upper wall of the right atrium."},
  {id:"ap030",subject:"Anatomy & Physiology",topic:"Endocrine",year:"Year 2",question:"ADH (antidiuretic hormone) is released from which gland?",options:["Anterior pituitary", "Adrenal medulla", "Posterior pituitary", "Thyroid gland"],answer:2,explanation:"ADH is synthesised in the hypothalamus but released from the posterior pituitary to promote water reabsorption."},
  {id:"fn001",subject:"Foundation of Nursing",topic:"History",year:"Year 1",question:"Florence Nightingale founded modern nursing following her work in which war?",options:["World War I", "Boer War", "Crimean War", "American Civil War"],answer:2,explanation:"Florence Nightingale reformed nursing care during the Crimean War (1853-1856), dramatically reducing mortality."},
  {id:"fn002",subject:"Foundation of Nursing",topic:"Nursing Process",year:"Year 1",question:"The FIRST step of the nursing process is:",options:["Planning", "Implementation", "Assessment", "Evaluation"],answer:2,explanation:"Assessment is the first step - gathering subjective and objective data to guide care planning."},
  {id:"fn003",subject:"Foundation of Nursing",topic:"Nursing Process",year:"Year 1",question:"A nursing diagnosis differs from a medical diagnosis in that it focuses on:",options:["Disease pathology", "Patient response to health problems", "Laboratory findings", "Prescribed treatments"],answer:1,explanation:"Nursing diagnoses describe the patient's response to health problems."},
  {id:"fn004",subject:"Foundation of Nursing",topic:"Infection Control",year:"Year 1",question:"Hand hygiene should be performed for at least how many seconds?",options:["5-10 seconds", "10-15 seconds", "20-30 seconds", "60 seconds"],answer:2,explanation:"The WHO recommends 20-30 seconds of hand rubbing or handwashing to be effective."},
  {id:"fn005",subject:"Foundation of Nursing",topic:"Infection Control",year:"Year 1",question:"Medical asepsis refers to:",options:["Complete elimination of all microorganisms", "Reduction of pathogenic microorganisms", "Sterilisation of all equipment", "Use of sterile gloves only"],answer:1,explanation:"Medical asepsis (clean technique) reduces the number and spread of pathogens."},
  {id:"fn006",subject:"Foundation of Nursing",topic:"Vital Signs",year:"Year 1",question:"Normal adult respiratory rate is:",options:["8-10 breaths/min", "12-20 breaths/min", "20-30 breaths/min", "30-40 breaths/min"],answer:1,explanation:"Normal adult respiratory rate is 12-20 breaths per minute."},
  {id:"fn007",subject:"Foundation of Nursing",topic:"Vital Signs",year:"Year 1",question:"A body temperature above which value indicates fever in adults?",options:["36.5 C", "37.0 C", "37.5 C", "38.0 C"],answer:3,explanation:"Fever is generally defined as a temperature above 38.0 degrees C; normal is 36.1-37.2 degrees C."},
  {id:"fn008",subject:"Foundation of Nursing",topic:"Documentation",year:"Year 1",question:"Nursing documentation should be:",options:["Vague to allow flexibility", "Completed after the shift ends", "Accurate timely and objective", "Written in pencil"],answer:2,explanation:"Documentation must be accurate, objective and timely; it is a legal record."},
  {id:"fn009",subject:"Foundation of Nursing",topic:"Ethics",year:"Year 1",question:"The ethical principle of doing good for the patient is called:",options:["Non-maleficence", "Justice", "Beneficence", "Autonomy"],answer:2,explanation:"Beneficence means acting in the patient's best interest and promoting their wellbeing."},
  {id:"fn010",subject:"Foundation of Nursing",topic:"Ethics",year:"Year 1",question:"Informed consent requires that a patient is:",options:["Over 18 years old only", "Competent informed and giving consent voluntarily", "Accompanied by a relative", "Diagnosed by a physician"],answer:1,explanation:"Valid informed consent needs: competent, adequately informed, and consent given voluntarily."},
  {id:"fn011",subject:"Foundation of Nursing",topic:"Bed Making",year:"Year 1",question:"When making an occupied bed, the patient should be positioned:",options:["Prone", "Supine flat", "In a lateral position to one side", "Sitting upright"],answer:2,explanation:"The patient is turned to a lateral position on one side while that half of the bed is made."},
  {id:"fn012",subject:"Foundation of Nursing",topic:"Patient Positioning",year:"Year 1",question:"The Trendelenburg position (head lower than feet) is used primarily for:",options:["Respiratory distress", "Shock and hypovolaemia", "Post-spinal anaesthesia", "Ascites drainage"],answer:1,explanation:"Trendelenburg position promotes venous return to the heart and is used in hypovolaemic shock."},
  {id:"fn013",subject:"Foundation of Nursing",topic:"Drug Administration",year:"Year 2",question:"The Five Rights of medication administration include all EXCEPT:",options:["Right patient", "Right route", "Right diagnosis", "Right dose"],answer:2,explanation:"The five rights are: right patient, right drug, right dose, right route, right time. Diagnosis is not one."},
  {id:"fn014",subject:"Foundation of Nursing",topic:"Wound Care",year:"Year 2",question:"The purpose of a pressure bandage on a bleeding wound is to:",options:["Promote infection prevention", "Apply direct pressure to stop bleeding", "Keep the wound moist", "Immobilise the limb"],answer:1,explanation:"A pressure bandage applies direct sustained pressure to a wound to promote haemostasis."},
  {id:"fn015",subject:"Foundation of Nursing",topic:"Communication",year:"Year 1",question:"Therapeutic communication in nursing involves:",options:["Giving advice quickly", "Telling patients what to do", "Active listening and empathy", "Talking about oneself"],answer:2,explanation:"Therapeutic communication uses active listening, open-ended questions, empathy and silence."},
  {id:"fn016",subject:"Foundation of Nursing",topic:"Pain Assessment",year:"Year 2",question:"The Numeric Rating Scale (NRS) for pain asks the patient to rate pain from:",options:["A to F", "1 to 5", "0 to 10", "1 to 100"],answer:2,explanation:"The NRS is a simple 0-10 scale where 0 = no pain and 10 = worst imaginable pain."},
  {id:"fn017",subject:"Foundation of Nursing",topic:"Infection Control",year:"Year 1",question:"PPE should be removed in which order?",options:["Gloves goggles gown mask", "Mask gloves gown goggles", "Gown gloves mask goggles", "Goggles mask gown gloves"],answer:0,explanation:"Remove gloves first (most contaminated), then goggles, then gown, then mask last."},
  {id:"fn018",subject:"Foundation of Nursing",topic:"Nursing Theory",year:"Year 1",question:"Maslow's Hierarchy of Needs places which category at the BASE?",options:["Safety needs", "Love and belonging", "Physiological needs", "Self-actualisation"],answer:2,explanation:"Physiological needs (air, water, food, warmth, sleep) are at the base of Maslow's hierarchy."},
  {id:"fn019",subject:"Foundation of Nursing",topic:"Fluid Balance",year:"Year 2",question:"Oedema is best described as:",options:["Excess fluid in blood vessels", "Abnormal accumulation of fluid in interstitial spaces", "Dehydration of cells", "Increased urine output"],answer:1,explanation:"Oedema is the abnormal accumulation of excess fluid in the interstitial (tissue) spaces."},
  {id:"fn020",subject:"Foundation of Nursing",topic:"Nursing Process",year:"Year 2",question:"Which statement best describes the evaluation step of the nursing process?",options:["Collecting patient data", "Writing nursing diagnoses", "Carrying out nursing interventions", "Determining whether goals have been met"],answer:3,explanation:"Evaluation compares the patient's current health status against the expected outcomes/goals."},
  {id:"ms001",subject:"Medical-Surgical Nursing",topic:"Cardiovascular",year:"Year 2",question:"The classic triad of myocardial infarction includes all EXCEPT:",options:["Chest pain radiating to left arm", "Diaphoresis", "Projectile vomiting", "Shortness of breath"],answer:2,explanation:"Classic MI presents with chest pain, diaphoresis and dyspnoea. Projectile vomiting is associated with raised ICP."},
  {id:"ms002",subject:"Medical-Surgical Nursing",topic:"Cardiovascular",year:"Year 2",question:"Nitroglycerin relieves angina primarily by:",options:["Increasing heart rate", "Dilating coronary blood vessels", "Reducing blood viscosity", "Increasing myocardial contractility"],answer:1,explanation:"Nitroglycerin dilates coronary vessels and reduces preload/afterload, improving myocardial oxygen supply."},
  {id:"ms003",subject:"Medical-Surgical Nursing",topic:"Respiratory",year:"Year 2",question:"The hallmark sign of asthma is:",options:["Productive cough only", "Persistent fever", "Reversible airway obstruction with wheeze", "Haemoptysis"],answer:2,explanation:"Asthma is characterised by reversible airway obstruction causing wheeze, cough and dyspnoea."},
  {id:"ms004",subject:"Medical-Surgical Nursing",topic:"Respiratory",year:"Year 2",question:"In caring for a patient with a chest tube, the nurse should:",options:["Clamp the tube routinely", "Keep the drainage system below chest level", "Strip the tube hourly", "Position the patient prone"],answer:1,explanation:"The drainage system must always be kept below chest level to allow gravity drainage."},
  {id:"ms005",subject:"Medical-Surgical Nursing",topic:"Neurological",year:"Year 2",question:"The Glasgow Coma Scale assesses:",options:["Only verbal response", "Eye opening verbal response and motor response", "Motor response only", "Pupil reaction and reflexes"],answer:1,explanation:"GCS assesses: eye opening (1-4), verbal response (1-5) and motor response (1-6); max score is 15."},
  {id:"ms006",subject:"Medical-Surgical Nursing",topic:"Neurological",year:"Year 2",question:"A patient with a stroke presents with left-sided weakness. The lesion is most likely in the:",options:["Left hemisphere", "Right hemisphere", "Cerebellum", "Brainstem"],answer:1,explanation:"Motor pathways cross (decussate); left-sided body weakness indicates a right hemisphere lesion."},
  {id:"ms007",subject:"Medical-Surgical Nursing",topic:"Renal",year:"Year 3",question:"A patient in acute renal failure is most likely to present with:",options:["Polyuria and low creatinine", "Oliguria and rising creatinine and urea", "Haematuria only", "Normal electrolytes"],answer:1,explanation:"Acute kidney injury presents with oliguria, rising creatinine and urea, and electrolyte disturbances."},
  {id:"ms008",subject:"Medical-Surgical Nursing",topic:"Renal",year:"Year 3",question:"Peritoneal dialysis works by:",options:["Filtering blood through a machine", "Using the peritoneum as a semi-permeable membrane", "Transplanting a kidney", "IV fluid replacement"],answer:1,explanation:"In peritoneal dialysis, the peritoneal membrane draws waste products by diffusion and osmosis."},
  {id:"ms009",subject:"Medical-Surgical Nursing",topic:"Endocrine",year:"Year 2",question:"Diabetic ketoacidosis (DKA) is characterised by:",options:["Hypoglycaemia and alkalosis", "Hyperglycaemia ketosis and metabolic acidosis", "Normal blood glucose with altered consciousness", "Hyponatraemia and bradycardia"],answer:1,explanation:"DKA features: hyperglycaemia, ketosis, metabolic acidosis (pH less than 7.35)."},
  {id:"ms010",subject:"Medical-Surgical Nursing",topic:"Endocrine",year:"Year 2",question:"Signs of hypoglycaemia include all EXCEPT:",options:["Tremors", "Diaphoresis", "Polyuria", "Confusion"],answer:2,explanation:"Hypoglycaemia causes tremors, diaphoresis and confusion. Polyuria is a sign of hyperglycaemia."},
  {id:"ms011",subject:"Medical-Surgical Nursing",topic:"Gastrointestinal",year:"Year 2",question:"Curling's ulcer is a stress ulcer specifically associated with:",options:["Head injuries", "Burns", "Renal failure", "Sepsis"],answer:1,explanation:"Curling's ulcers are acute stress ulcers of the duodenum associated with severe burns."},
  {id:"ms012",subject:"Medical-Surgical Nursing",topic:"Gastrointestinal",year:"Year 2",question:"Jaundice results from accumulation of which substance?",options:["Urea", "Bilirubin", "Creatinine", "Albumin"],answer:1,explanation:"Jaundice is caused by elevated bilirubin causing yellow discolouration of skin, sclerae and mucosae."},
  {id:"ms013",subject:"Medical-Surgical Nursing",topic:"Musculoskeletal",year:"Year 2",question:"The five Ps of compartment syndrome are pain pulselessness paraesthesia paralysis and:",options:["Pallor", "Pyrexia", "Pruritus", "Pressure"],answer:0,explanation:"The 5 Ps: Pain (on passive stretch), Pallor, Pulselessness, Paraesthesia, Paralysis."},
  {id:"ms014",subject:"Medical-Surgical Nursing",topic:"Musculoskeletal",year:"Year 2",question:"Buck's traction is used for:",options:["Cervical spine injuries", "Temporary immobilisation of hip/femur fractures", "Scoliosis correction", "Open fractures"],answer:1,explanation:"Buck's traction is a skin traction for temporary immobilisation before surgical fixation of hip and femur fractures."},
  {id:"ms015",subject:"Medical-Surgical Nursing",topic:"Postoperative",year:"Year 2",question:"In the immediate post-anaesthesia period, the PRIORITY nursing assessment is:",options:["Pain level", "Urinary output", "Airway patency and breathing", "Skin integrity"],answer:2,explanation:"Airway and breathing are the priority - airway obstruction is the most life-threatening immediate post-op complication."},
  {id:"ms016",subject:"Medical-Surgical Nursing",topic:"Postoperative",year:"Year 2",question:"Deep vein thrombosis (DVT) prevention post-operatively includes:",options:["Prolonged bed rest", "Early ambulation and compression stockings", "Dehydration", "Leg restraints"],answer:1,explanation:"DVT prevention: early ambulation, leg exercises, compression stockings, adequate hydration."},
  {id:"ms017",subject:"Medical-Surgical Nursing",topic:"Haematological",year:"Year 3",question:"Sickle cell crisis is primarily triggered by:",options:["High oxygen levels", "Hypoxia dehydration and cold", "Excessive fluid intake", "High altitude only"],answer:1,explanation:"Sickle cell vaso-occlusive crises are triggered by hypoxia, dehydration, infection and cold temperatures."},
  {id:"ms018",subject:"Medical-Surgical Nursing",topic:"Haematological",year:"Year 3",question:"A patient receiving a blood transfusion develops fever chills and flank pain. The nurse should first:",options:["Slow the transfusion rate", "Administer paracetamol", "Stop the transfusion immediately", "Apply ice packs"],answer:2,explanation:"These are signs of an acute haemolytic transfusion reaction - stop the transfusion immediately."},
  {id:"ms019",subject:"Medical-Surgical Nursing",topic:"Oncology",year:"Year 3",question:"Chemotherapy-induced neutropenia increases the patient's risk of:",options:["Bleeding only", "Serious infection and sepsis", "Hyperglycaemia", "Fluid overload"],answer:1,explanation:"Neutropenia from chemotherapy severely impairs immunity, making patients susceptible to life-threatening infections."},
  {id:"ms020",subject:"Medical-Surgical Nursing",topic:"Oncology",year:"Year 3",question:"The 7 warning signs of cancer are remembered with the acronym:",options:["DANGER", "CAUTION", "CANCER", "BEWARE"],answer:1,explanation:"CAUTION: Change in bowel/bladder, A sore that won't heal, Unusual bleeding, Thickening/lump, Indigestion, Obvious change, Nagging cough."},
  {id:"ms021",subject:"Medical-Surgical Nursing",topic:"Special Senses",year:"Year 3",question:"Following cataract surgery, a nurse instructs the patient to avoid:",options:["Wearing sunglasses", "Taking prescribed eye drops", "Bending forward or straining", "Sleeping on back"],answer:2,explanation:"Activities that increase intraocular pressure (IOP) such as bending or straining must be avoided."},
  {id:"ms022",subject:"Medical-Surgical Nursing",topic:"Special Senses",year:"Year 3",question:"Conductive hearing loss occurs due to problems in the:",options:["Cochlea", "Auditory nerve", "External or middle ear", "Brain cortex"],answer:2,explanation:"Conductive hearing loss is caused by problems transmitting sound waves through the external canal or ossicles."},
  {id:"ms023",subject:"Medical-Surgical Nursing",topic:"Cardiovascular",year:"Year 2",question:"Pitting oedema is graded on a scale of:",options:["0 to 2+", "1+ to 4+", "A to D", "0 to 10"],answer:1,explanation:"Pitting oedema is graded 1+ (mild, 2mm) to 4+ (severe, 8mm or more)."},
  {id:"ms024",subject:"Medical-Surgical Nursing",topic:"Respiratory",year:"Year 2",question:"Pulse oximetry measures:",options:["Arterial blood gas pH", "Peripheral oxygen saturation SpO2", "Expired CO2", "Lung capacity"],answer:1,explanation:"Pulse oximetry non-invasively measures peripheral oxygen saturation (SpO2) using light absorption."},
  {id:"ms025",subject:"Medical-Surgical Nursing",topic:"Endocrine",year:"Year 2",question:"The Chvostek sign (facial muscle spasm on tapping) indicates:",options:["Hyperkalaemia", "Hypocalcaemia", "Hypernatraemia", "Hypomagnesaemia"],answer:1,explanation:"Chvostek's sign indicates hypocalcaemia; tapping the facial nerve causes ipsilateral facial muscle twitching."},
  {id:"ms026",subject:"Medical-Surgical Nursing",topic:"Gastrointestinal",year:"Year 2",question:"In liver cirrhosis the nurse monitors for hepatic encephalopathy by assessing:",options:["Blood pressure only", "Level of consciousness and asterixis (flapping tremor)", "Skin turgor", "Urinary output only"],answer:1,explanation:"Hepatic encephalopathy presents with altered LOC and asterixis due to ammonia accumulation."},
  {id:"ms027",subject:"Medical-Surgical Nursing",topic:"Renal",year:"Year 3",question:"Patients on peritoneal dialysis are at high risk for which complication?",options:["Haemothorax", "Peritonitis", "Pneumonia", "Deep vein thrombosis"],answer:1,explanation:"Peritonitis is the most common and serious complication of peritoneal dialysis."},
  {id:"ms028",subject:"Medical-Surgical Nursing",topic:"Neurological",year:"Year 2",question:"Nursing care for a patient having a tonic-clonic seizure includes:",options:["Restraining the patient", "Inserting a tongue depressor", "Protecting from injury and timing the seizure", "Giving oral medication"],answer:2,explanation:"During a seizure: protect from injury, time it, do NOT restrain, do NOT insert anything in mouth; position laterally after."},
  {id:"ms029",subject:"Medical-Surgical Nursing",topic:"Burns",year:"Year 2",question:"The Rule of Nines is used to estimate:",options:["Fluid resuscitation volume", "Total body surface area (TBSA) burned", "Burn depth", "Infection risk"],answer:1,explanation:"The Rule of Nines assigns 9% to body regions to estimate TBSA burned for fluid resuscitation."},
  {id:"ms030",subject:"Medical-Surgical Nursing",topic:"Burns",year:"Year 2",question:"The Parkland formula for burn fluid resuscitation uses:",options:["Normal saline only", "Dextrose 5%", "Ringers Lactate 4ml per kg per percent TBSA", "Blood products initially"],answer:2,explanation:"Parkland formula: 4ml x weight (kg) x %TBSA burned of Ringer's Lactate in the first 24 hours."},
  {id:"ms031",subject:"Medical-Surgical Nursing",topic:"Cardiovascular",year:"Year 2",question:"Which sign indicates left-sided heart failure?",options:["Peripheral oedema", "Pulmonary oedema and crackles at lung bases", "Hepatomegaly", "Jugular vein distension"],answer:1,explanation:"Left heart failure causes pulmonary congestion. Right heart failure causes systemic congestion (peripheral oedema, JVD)."},
  {id:"ms032",subject:"Medical-Surgical Nursing",topic:"Postoperative",year:"Year 2",question:"Atelectasis post-operatively is best prevented by:",options:["Restricting fluids", "Deep breathing exercises and use of incentive spirometry", "Complete bed rest", "Early nasogastric tube removal"],answer:1,explanation:"Deep breathing, coughing and incentive spirometry expand collapsed alveoli, preventing post-op atelectasis."},
  {id:"ms033",subject:"Medical-Surgical Nursing",topic:"Haematological",year:"Year 3",question:"In disseminated intravascular coagulation (DIC), the patient is at risk of:",options:["Thrombosis only", "Bleeding only", "Both thrombosis and bleeding simultaneously", "Anaemia only"],answer:2,explanation:"DIC is paradoxical: clotting consumes clotting factors, leading to both microvascular thrombosis and uncontrolled bleeding."},
  {id:"ms034",subject:"Medical-Surgical Nursing",topic:"Gastrointestinal",year:"Year 2",question:"Nursing care for a patient with an ileostomy includes:",options:["Expecting formed stool output", "Monitoring for dehydration and electrolyte loss", "Restricting fluids", "Not changing the bag for 7 days"],answer:1,explanation:"Ileostomy output is liquid to semi-liquid; patients are at risk of dehydration and electrolyte loss."},
  {id:"ms035",subject:"Medical-Surgical Nursing",topic:"Oncology",year:"Year 3",question:"Palliative care focuses on:",options:["Curing terminal disease", "Relieving symptoms and improving quality of life", "Aggressive treatment continuation", "Withholding all treatment"],answer:1,explanation:"Palliative care focuses on relief of pain and symptoms, and improving quality of life."},
  {id:"ph001",subject:"Pharmacology",topic:"Drug Actions",year:"Year 1",question:"The term half-life of a drug refers to the time required to:",options:["Absorb 50% of a dose", "Reduce plasma concentration by 50%", "Eliminate the drug completely", "Reach peak effect"],answer:1,explanation:"Drug half-life is the time required for plasma drug concentration to decrease by 50%."},
  {id:"ph002",subject:"Pharmacology",topic:"Drug Actions",year:"Year 1",question:"First-pass metabolism occurs in the:",options:["Kidneys", "Lungs", "Liver", "Small intestine"],answer:2,explanation:"First-pass metabolism is the extensive hepatic metabolism of oral drugs before reaching systemic circulation."},
  {id:"ph003",subject:"Pharmacology",topic:"Antibiotics",year:"Year 2",question:"Penicillin works by:",options:["Inhibiting protein synthesis", "Disrupting cell membrane", "Inhibiting cell wall synthesis", "Inhibiting DNA replication"],answer:2,explanation:"Penicillins inhibit transpeptidase enzymes, disrupting bacterial cell wall (peptidoglycan) synthesis."},
  {id:"ph004",subject:"Pharmacology",topic:"Antibiotics",year:"Year 2",question:"The most serious adverse effects of aminoglycoside antibiotics are:",options:["Nephrotoxicity and ototoxicity", "Hepatotoxicity", "Bone marrow suppression", "Stevens-Johnson syndrome"],answer:0,explanation:"Aminoglycosides (gentamicin, streptomycin) cause dose-dependent nephrotoxicity and ototoxicity."},
  {id:"ph005",subject:"Pharmacology",topic:"Cardiovascular Drugs",year:"Year 2",question:"Digoxin toxicity is potentiated by:",options:["Hypernatraemia", "Hyperkalaemia", "Hypokalaemia", "Hypermagnesaemia"],answer:2,explanation:"Hypokalaemia increases binding of digoxin to Na+/K+ ATPase, enhancing toxicity."},
  {id:"ph006",subject:"Pharmacology",topic:"Cardiovascular Drugs",year:"Year 2",question:"A common side effect of ACE inhibitors is:",options:["Hyperkalaemia and dry cough", "Constipation", "Bradycardia", "Hypokalaemia"],answer:0,explanation:"ACE inhibitors cause dry persistent cough (due to bradykinin accumulation) and hyperkalaemia."},
  {id:"ph007",subject:"Pharmacology",topic:"Analgesics",year:"Year 2",question:"Which analgesic should be used with CAUTION in patients with peptic ulcer disease?",options:["Paracetamol", "Aspirin and NSAIDs", "Morphine", "Codeine"],answer:1,explanation:"NSAIDs reduce protective prostaglandins, causing gastric mucosal damage and worsening peptic ulcers."},
  {id:"ph008",subject:"Pharmacology",topic:"Analgesics",year:"Year 2",question:"Overdose of paracetamol primarily causes damage to the:",options:["Kidneys", "Heart", "Liver", "Lungs"],answer:2,explanation:"Paracetamol overdose depletes hepatic glutathione; the toxic metabolite NAPQI causes hepatocellular necrosis."},
  {id:"ph009",subject:"Pharmacology",topic:"CNS Drugs",year:"Year 2",question:"Benzodiazepines work by enhancing the action of which neurotransmitter?",options:["Dopamine", "Serotonin", "GABA", "Acetylcholine"],answer:2,explanation:"Benzodiazepines bind to GABA-A receptors, producing anxiolysis, sedation and anticonvulsant effects."},
  {id:"ph010",subject:"Pharmacology",topic:"CNS Drugs",year:"Year 2",question:"Antipsychotic drugs primarily work by blocking which receptor?",options:["Serotonin 5-HT1A", "Dopamine D2", "GABA-A", "Acetylcholine muscarinic"],answer:1,explanation:"Typical and atypical antipsychotics primarily block dopamine D2 receptors, reducing positive symptoms of schizophrenia."},
  {id:"ph011",subject:"Pharmacology",topic:"Endocrine Drugs",year:"Year 2",question:"Which insulin type has the LONGEST duration of action?",options:["Regular soluble insulin", "NPH insulin", "Glargine (Lantus)", "Lispro (Humalog)"],answer:2,explanation:"Insulin glargine is a long-acting basal insulin with a duration of about 24 hours and no pronounced peak."},
  {id:"ph012",subject:"Pharmacology",topic:"Endocrine Drugs",year:"Year 2",question:"Metformin is the first-line drug for Type 2 diabetes because it:",options:["Stimulates insulin secretion", "Reduces insulin resistance and hepatic glucose output", "Replaces insulin", "Blocks glucose absorption"],answer:1,explanation:"Metformin reduces hepatic glucose production, improves insulin sensitivity, and does not cause hypoglycaemia."},
  {id:"ph013",subject:"Pharmacology",topic:"Antimalarials",year:"Year 1",question:"The first-line treatment for uncomplicated malaria in Nigeria is:",options:["Chloroquine", "Quinine", "Artemisinin-based Combination Therapy (ACT)", "Doxycycline"],answer:2,explanation:"Nigeria's NMCP guidelines recommend ACTs (e.g. artemether-lumefantrine) as first-line for uncomplicated malaria."},
  {id:"ph014",subject:"Pharmacology",topic:"Respiratory Drugs",year:"Year 2",question:"Salbutamol (albuterol) is classified as a:",options:["Corticosteroid", "Short-acting beta-2 agonist (SABA)", "Muscarinic antagonist", "Leukotriene receptor antagonist"],answer:1,explanation:"Salbutamol is a SABA that relaxes bronchial smooth muscle by stimulating beta-2 adrenergic receptors."},
  {id:"ph015",subject:"Pharmacology",topic:"Anticoagulants",year:"Year 3",question:"The antidote for heparin overdose is:",options:["Vitamin K", "Protamine sulphate", "Fresh frozen plasma", "Naloxone"],answer:1,explanation:"Protamine sulphate binds and neutralises heparin. Vitamin K reverses warfarin; naloxone reverses opioids."},
  {id:"ph016",subject:"Pharmacology",topic:"Drug Administration",year:"Year 1",question:"The route of administration with the FASTEST onset of action is:",options:["Oral", "Subcutaneous", "Intramuscular", "Intravenous"],answer:3,explanation:"IV administration bypasses absorption entirely, delivering drug directly into systemic circulation."},
  {id:"ph017",subject:"Pharmacology",topic:"Antibiotics",year:"Year 2",question:"Antibiotic-associated diarrhoea after clindamycin is most likely caused by:",options:["Staphylococcus aureus", "Candida albicans", "Clostridioides difficile", "Salmonella typhi"],answer:2,explanation:"C. difficile overgrowth causing pseudomembranous colitis is a common complication of clindamycin."},
  {id:"ph018",subject:"Pharmacology",topic:"Opioids",year:"Year 2",question:"Classic signs of opioid overdose include:",options:["Dilated pupils tachycardia hyperthermia", "Pinpoint pupils respiratory depression reduced consciousness", "Agitation hypoglycaemia seizures", "Dry mouth urinary retention tachycardia"],answer:1,explanation:"Opioid toxidrome: miosis (pinpoint pupils), respiratory depression, reduced consciousness."},
  {id:"ph019",subject:"Pharmacology",topic:"Cardiovascular Drugs",year:"Year 2",question:"Which drug is used to reverse bradycardia in emergency settings?",options:["Adrenaline high dose", "Atropine", "Lignocaine", "Adenosine"],answer:1,explanation:"Atropine blocks muscarinic receptors, increasing heart rate; it is first-line for symptomatic bradycardia."},
  {id:"ph020",subject:"Pharmacology",topic:"ARVs",year:"Year 2",question:"Antiretroviral therapy (ART) for HIV works primarily by:",options:["Killing all HIV viruses immediately", "Suppressing viral replication to undetectable levels", "Boosting CD4 count directly", "Preventing HIV entry only"],answer:1,explanation:"ART suppresses HIV replication, allowing immune recovery and reducing viral load to undetectable levels."},
  {id:"rh001",subject:"Reproductive Health",topic:"Antenatal",year:"Year 2",question:"Naegele's rule for estimated date of delivery (EDD) involves:",options:["Adding 280 days to conception date", "Last menstrual period plus 9 months and 7 days", "Subtracting 3 months from current date", "Using fundal height only"],answer:1,explanation:"Naegele's rule: EDD = LMP + 9 months + 7 days. Assumes regular 28-day cycle."},
  {id:"rh002",subject:"Reproductive Health",topic:"Antenatal",year:"Year 2",question:"Eclampsia is defined as pre-eclampsia complicated by:",options:["Proteinuria", "Hypertension above 160/110", "Convulsions or seizures", "Severe headache"],answer:2,explanation:"Eclampsia is the occurrence of grand mal seizures in a woman with pre-eclampsia."},
  {id:"rh003",subject:"Reproductive Health",topic:"Antenatal",year:"Year 2",question:"The partograph is used to monitor:",options:["Foetal heart rate only", "Progress of labour", "Maternal blood pressure only", "Antenatal weight gain"],answer:1,explanation:"The partograph graphically records observations of mother and foetus and progress of labour."},
  {id:"rh004",subject:"Reproductive Health",topic:"Labour",year:"Year 2",question:"The first stage of labour ends with:",options:["Delivery of the placenta", "Full cervical dilatation (10 cm)", "Rupture of membranes", "Crowning of the baby's head"],answer:1,explanation:"The first stage ends with complete cervical dilatation (10 cm)."},
  {id:"rh005",subject:"Reproductive Health",topic:"Labour",year:"Year 2",question:"Active management of the third stage of labour (AMTSL) includes:",options:["Watchful waiting only", "Oxytocin plus controlled cord traction plus uterine massage", "Immediate manual removal of placenta", "Episiotomy routinely"],answer:1,explanation:"AMTSL: oxytocin 10IU IM within 1 min of birth, controlled cord traction, uterine massage after delivery."},
  {id:"rh006",subject:"Reproductive Health",topic:"Postpartum",year:"Year 2",question:"Primary postpartum haemorrhage (PPH) is defined as blood loss exceeding:",options:["100 ml within 24 hours", "500 ml within 24 hours of vaginal delivery", "200 ml at any time", "1000 ml within 72 hours"],answer:1,explanation:"Primary PPH: 500 ml or more blood loss within 24 hours of vaginal delivery."},
  {id:"rh007",subject:"Reproductive Health",topic:"Postpartum",year:"Year 2",question:"The 4Ts causes of postpartum haemorrhage are Tone Trauma Tissue and:",options:["Thrombosis", "Temperature", "Tachycardia", "Thrombin (coagulopathy)"],answer:3,explanation:"The 4Ts: Tone (uterine atony 80%), Trauma (lacerations), Tissue (retained products), Thrombin (coagulopathy)."},
  {id:"rh008",subject:"Reproductive Health",topic:"Family Planning",year:"Year 2",question:"Combined oral contraceptive pills work PRIMARILY by:",options:["Thickening cervical mucus only", "Inhibiting ovulation via hypothalamic-pituitary axis suppression", "Creating hostile endometrium only", "Preventing fertilisation mechanically"],answer:1,explanation:"COCPs primarily suppress ovulation by inhibiting GnRH, LH and FSH."},
  {id:"rh009",subject:"Reproductive Health",topic:"Family Planning",year:"Year 2",question:"The IUCD (intrauterine device) is contraindicated in:",options:["Multiparous women", "Women with active pelvic inflammatory disease or copper allergy", "Women over 35", "Breastfeeding mothers"],answer:1,explanation:"Absolute contraindications to IUCD: active PID/STI, unexplained vaginal bleeding, copper allergy, pregnancy."},
  {id:"rh010",subject:"Reproductive Health",topic:"Abortion",year:"Year 2",question:"A threatened abortion is characterised by:",options:["Dilated cervix with bleeding", "Vaginal bleeding with closed cervix and pregnancy may continue", "Complete expulsion of products", "Incomplete expulsion with open cervix"],answer:1,explanation:"Threatened abortion: vaginal bleeding, cervix CLOSED, foetal heartbeat present - pregnancy may continue."},
  {id:"rh011",subject:"Reproductive Health",topic:"Paediatrics",year:"Year 3",question:"The normal birth weight for a term neonate is:",options:["1.5-2.0 kg", "2.0-2.5 kg", "2.5-4.0 kg", "4.0-5.0 kg"],answer:2,explanation:"Normal birth weight is 2.5-4.0 kg; below 2.5 kg is low birth weight; above 4.0 kg is macrosomia."},
  {id:"rh012",subject:"Reproductive Health",topic:"Paediatrics",year:"Year 3",question:"The Apgar score is assessed at:",options:["Birth only", "1 minute and 5 minutes after birth", "10 minutes after birth", "30 minutes after birth"],answer:1,explanation:"Apgar score (Appearance Pulse Grimace Activity Respiration) is assessed at 1 and 5 minutes; 7-10 is normal."},
  {id:"rh013",subject:"Reproductive Health",topic:"Paediatrics",year:"Year 3",question:"Exclusive breastfeeding is recommended for the first:",options:["2 months", "4 months", "6 months", "12 months"],answer:2,explanation:"WHO/UNICEF recommend exclusive breastfeeding (no water, juice or food) for the first 6 months of life."},
  {id:"rh014",subject:"Reproductive Health",topic:"Adolescent",year:"Year 3",question:"The onset of menstruation in girls is called:",options:["Menopause", "Thelarche", "Menarche", "Adrenarche"],answer:2,explanation:"Menarche is the first menstruation; thelarche is breast development; adrenarche is adrenal puberty (pubic hair)."},
  {id:"rh015",subject:"Reproductive Health",topic:"Complications",year:"Year 2",question:"Shoulder dystocia is best managed with the:",options:["Pinard manoeuvre", "McRoberts manoeuvre and suprapubic pressure", "Kristeller manoeuvre", "Ritgen manoeuvre"],answer:1,explanation:"McRoberts manoeuvre plus suprapubic pressure is the first-line management for shoulder dystocia."},
  {id:"rh016",subject:"Reproductive Health",topic:"Antenatal",year:"Year 2",question:"Iron deficiency anaemia in pregnancy is treated with:",options:["Blood transfusion only", "Oral ferrous sulphate and folic acid", "Vitamin B12 injections", "Dietary advice alone"],answer:1,explanation:"Mild-moderate iron deficiency anaemia in pregnancy is treated with oral ferrous sulphate plus folic acid."},
  {id:"rh017",subject:"Reproductive Health",topic:"Complications",year:"Year 2",question:"Antepartum haemorrhage (APH) is defined as bleeding from the genital tract after:",options:["12 weeks", "20 weeks", "28 weeks of gestation", "36 weeks only"],answer:2,explanation:"APH is bleeding from the genital tract after 28 weeks gestation but before delivery of the baby."},
  {id:"rh018",subject:"Reproductive Health",topic:"Antenatal",year:"Year 2",question:"Fundal height in cm roughly equals gestational age in weeks between:",options:["8-12 weeks", "16-36 weeks", "From conception", "After 36 weeks only"],answer:1,explanation:"Between 16-36 weeks, fundal height in centimetres approximately equals gestational age in weeks (McDonald's rule)."},
  {id:"rh019",subject:"Reproductive Health",topic:"Neonatal",year:"Year 3",question:"Prevention of ophthalmia neonatorum is achieved by instilling:",options:["Steroid drops", "Tetracycline 1% or erythromycin eye ointment", "Chloramphenicol drops", "Normal saline only"],answer:1,explanation:"Tetracycline 1% or erythromycin eye ointment at birth prevents gonococcal and chlamydial neonatal conjunctivitis."},
  {id:"rh020",subject:"Reproductive Health",topic:"Family Planning",year:"Year 2",question:"Emergency contraception is most effective when taken within:",options:["24 hours", "72 hours", "1 week", "2 weeks"],answer:1,explanation:"Levonorgestrel emergency contraception is most effective within 72 hours (3 days) of unprotected sex."},
  {id:"rh021",subject:"Reproductive Health",topic:"Labour",year:"Year 2",question:"Bloody show at the onset of labour results from:",options:["Rupture of membranes", "Loss of the cervical mucus plug mixed with blood", "Uterine rupture", "Placental separation"],answer:1,explanation:"Show is the expulsion of the blood-stained cervical mucus plug as the cervix begins to efface and dilate."},
  {id:"rh022",subject:"Reproductive Health",topic:"Postpartum",year:"Year 2",question:"Puerperal sepsis most commonly arises from infection of the:",options:["Urinary tract only", "Uterus (endometritis)", "Breast", "Perineal wound"],answer:1,explanation:"Puerperal sepsis is primarily uterine infection (endometritis) caused by ascending bacteria."},
  {id:"rh023",subject:"Reproductive Health",topic:"Paediatrics",year:"Year 3",question:"In IMCI a child with fast breathing AND chest in-drawing should be classified as:",options:["No pneumonia", "Non-severe pneumonia", "Severe pneumonia", "Upper respiratory infection"],answer:2,explanation:"IMCI: fast breathing alone = non-severe pneumonia; plus chest in-drawing = severe pneumonia requiring referral."},
  {id:"rh024",subject:"Reproductive Health",topic:"Paediatrics",year:"Year 3",question:"BCG vaccine provides protection against:",options:["Polio", "Measles", "Tuberculosis especially TB meningitis in infants", "Yellow fever"],answer:2,explanation:"BCG primarily protects infants from severe forms of TB like TB meningitis and miliary TB."},
  {id:"rh025",subject:"Reproductive Health",topic:"Adolescent",year:"Year 3",question:"The most effective way to prevent teenage pregnancy is:",options:["Providing contraception only", "Comprehensive sexuality education and youth-friendly health services", "Restricting adolescent freedom", "Early marriage"],answer:1,explanation:"Comprehensive sexuality education plus access to contraception and youth-friendly services is most effective."},
  {id:"ch001",subject:"Community Health Nursing",topic:"PHC Principles",year:"Year 1",question:"Primary Health Care (PHC) was declared at the Alma Ata Conference in:",options:["1948", "1968", "1978", "1988"],answer:2,explanation:"The Declaration of Alma-Ata was adopted at the International Conference on PHC in 1978."},
  {id:"ch002",subject:"Community Health Nursing",topic:"PHC Principles",year:"Year 1",question:"The first component of PHC in Nigeria is:",options:["Essential medicines supply", "Health education", "Medical care", "Environmental sanitation"],answer:1,explanation:"Health education and community participation is the first listed component of PHC."},
  {id:"ch003",subject:"Community Health Nursing",topic:"Epidemiology",year:"Year 3",question:"Incidence rate measures:",options:["Total existing cases in a population", "New cases occurring in a defined period", "Deaths from a disease", "Severity of a disease"],answer:1,explanation:"Incidence = new cases in a defined time period / population at risk."},
  {id:"ch004",subject:"Community Health Nursing",topic:"Epidemiology",year:"Year 3",question:"The herd immunity threshold for measles is approximately:",options:["50-60%", "70-75%", "92-95%", "99-100%"],answer:2,explanation:"Measles requires 92-95% population immunity for herd protection due to its high transmissibility."},
  {id:"ch005",subject:"Community Health Nursing",topic:"Disease Control",year:"Year 3",question:"Quarantine differs from isolation in that quarantine applies to:",options:["Confirmed cases", "Exposed but not yet symptomatic individuals", "Healthcare workers only", "Those already recovered"],answer:1,explanation:"Isolation separates confirmed cases; quarantine separates exposed, potentially incubating individuals."},
  {id:"ch006",subject:"Community Health Nursing",topic:"Maternal and Child Health",year:"Year 2",question:"Antenatal care contacts recommended by WHO 2016 guidelines are:",options:["At least 4 visits", "At least 6 visits", "At least 8 contacts", "At least 12 visits"],answer:2,explanation:"The 2016 WHO ANC model recommends a minimum of 8 contacts during pregnancy."},
  {id:"ch007",subject:"Community Health Nursing",topic:"Immunisation",year:"Year 2",question:"The cold chain in immunisation refers to:",options:["Air-conditioned storage only", "The temperature-controlled supply chain for vaccines at 2-8 degrees C", "Freezing all vaccines at -20 degrees C", "Hospital refrigerators only"],answer:1,explanation:"The cold chain is the temperature-controlled (2-8 degrees C) system from manufacture to administration."},
  {id:"ch008",subject:"Community Health Nursing",topic:"School Health",year:"Year 2",question:"A school health nurse's PRIMARY role is:",options:["Treating all illnesses", "Teaching academic subjects", "Health promotion disease prevention and first aid", "Administering exams"],answer:2,explanation:"School health nursing focuses on health promotion, preventive services, first aid and health education."},
  {id:"ch009",subject:"Community Health Nursing",topic:"Occupational Health",year:"Year 2",question:"Occupational lung disease (pneumoconiosis) in miners is caused by inhalation of:",options:["Chemicals", "Mineral dust (silica, coal)", "Bacteria", "Heat stress"],answer:1,explanation:"Pneumoconiosis results from prolonged inhalation of mineral dusts causing progressive lung fibrosis."},
  {id:"ch010",subject:"Community Health Nursing",topic:"Harmful Traditional Practices",year:"Year 2",question:"Female Genital Mutilation (FGM) is classified by WHO into how many types?",options:["2", "3", "4", "6"],answer:2,explanation:"WHO classifies FGM into 4 types: Type I (clitoridectomy), Type II (excision), Type III (infibulation), Type IV (other)."},
  {id:"ch011",subject:"Community Health Nursing",topic:"Disease Control",year:"Year 3",question:"Cholera is transmitted via the:",options:["Air", "Faecal-oral route (contaminated water/food)", "Blood transfusion", "Vector (mosquito)"],answer:1,explanation:"Cholera is transmitted by ingesting contaminated water or food. It is endemic in areas with poor sanitation."},
  {id:"ch012",subject:"Community Health Nursing",topic:"Disease Control",year:"Year 3",question:"The definitive host of the malaria parasite Plasmodium falciparum is the:",options:["Human", "Anopheles mosquito", "Culex mosquito", "Aedes mosquito"],answer:1,explanation:"The Anopheles female mosquito is the definitive (sexual) host; humans are the intermediate (asexual) host."},
  {id:"ch013",subject:"Community Health Nursing",topic:"Health Statistics",year:"Year 3",question:"Maternal mortality ratio (MMR) is expressed per:",options:["1,000 live births", "10,000 live births", "100,000 live births", "1,000,000 population"],answer:2,explanation:"MMR = (maternal deaths / live births) x 100,000. It measures obstetric risk per pregnancy."},
  {id:"ch014",subject:"Community Health Nursing",topic:"Health Statistics",year:"Year 3",question:"Infant mortality rate (IMR) is expressed as deaths per:",options:["100 live births", "1,000 live births", "10,000 population", "1,000 total population"],answer:1,explanation:"IMR = deaths of infants under 1 year / 1,000 live births - a key indicator of population health."},
  {id:"ch015",subject:"Community Health Nursing",topic:"Non-Communicable Diseases",year:"Year 3",question:"The behavioural risk factors for NCDs include all EXCEPT:",options:["Tobacco use", "Physical inactivity", "Malaria infection", "Harmful use of alcohol"],answer:2,explanation:"The four shared modifiable NCD risk factors are tobacco, physical inactivity, unhealthy diet and harmful alcohol use."},
  {id:"ch016",subject:"Community Health Nursing",topic:"Epidemiology",year:"Year 3",question:"An epidemic is defined as:",options:["A disease constantly present in a community", "Disease cases exceeding normal expectancy in a community", "A worldwide disease spread", "A disease affecting only one person"],answer:1,explanation:"An epidemic is an occurrence of cases exceeding what would normally be expected in that community."},
  {id:"ch017",subject:"Community Health Nursing",topic:"Maternal and Child Health",year:"Year 2",question:"Growth monitoring in children uses which primary tool?",options:["Temperature chart", "Road-to-Health growth monitoring chart", "Apgar chart", "Fluid balance chart"],answer:1,explanation:"The Road-to-Health chart plots weight-for-age to track child growth and nutritional status."},
  {id:"ch018",subject:"Community Health Nursing",topic:"Water and Sanitation",year:"Year 1",question:"Safe water supply is critical in preventing diseases spread by:",options:["Airborne route only", "Faecal-oral (waterborne) route", "Vector-borne route", "Sexual contact"],answer:1,explanation:"Waterborne diseases (cholera, typhoid, dysentery, hepatitis A) are prevented by safe water and sanitation."},
  {id:"ch019",subject:"Community Health Nursing",topic:"Immunisation",year:"Year 2",question:"Which vaccine should NOT be given to severely immunocompromised patients?",options:["Inactivated polio vaccine (IPV)", "Oral polio vaccine (OPV)", "Hepatitis B vaccine", "Tetanus toxoid"],answer:1,explanation:"Live attenuated vaccines (OPV, BCG, MMR, yellow fever) are contraindicated in severely immunocompromised patients."},
  {id:"ch020",subject:"Community Health Nursing",topic:"Health Education",year:"Year 1",question:"The BEST method of health education for an illiterate community is:",options:["Written pamphlets", "Lectures using technical terms", "Demonstrations and community drama using local language", "Television programmes"],answer:2,explanation:"Demonstrations, community drama and visual aids in local languages are most effective for low-literacy communities."},
  {id:"mb001",subject:"Microbiology",topic:"Bacteria",year:"Year 1",question:"Bacteria are classified as prokaryotes because they:",options:["Have mitochondria", "Lack a membrane-bound nucleus", "Have a nucleus", "Are multicellular"],answer:1,explanation:"Prokaryotes lack a membrane-bound nucleus; their DNA is in the cytoplasm as a nucleoid."},
  {id:"mb002",subject:"Microbiology",topic:"Gram Stain",year:"Year 1",question:"Gram-positive bacteria appear which colour after Gram staining?",options:["Pink/red", "Blue/purple", "Yellow", "Colourless"],answer:1,explanation:"Gram-positive bacteria retain the crystal violet stain (appear blue/purple) due to their thick peptidoglycan cell wall."},
  {id:"mb003",subject:"Microbiology",topic:"Sterilisation",year:"Year 1",question:"Autoclaving sterilises by using:",options:["Dry heat", "UV radiation", "Saturated steam under pressure (121 degrees C, 15 psi)", "Chemical agents"],answer:2,explanation:"Autoclaving uses saturated steam at 121 degrees C under 15 psi for 15-20 minutes, killing all microorganisms including spores."},
  {id:"mb004",subject:"Microbiology",topic:"Viruses",year:"Year 1",question:"Viruses are obligate intracellular parasites because they:",options:["Can only survive in water", "Must use host cell machinery to replicate", "Are always pathogenic", "Are visible under a light microscope"],answer:1,explanation:"Viruses lack cellular machinery for independent reproduction and must use host cell ribosomes and enzymes."},
  {id:"mb005",subject:"Microbiology",topic:"HIV",year:"Year 2",question:"HIV primarily infects which type of immune cell?",options:["B lymphocytes", "CD8+ T cells", "CD4+ T helper cells", "Natural killer cells"],answer:2,explanation:"HIV uses gp120 to bind to CD4 receptors on CD4+ T helper cells, macrophages and dendritic cells."},
  {id:"mb006",subject:"Microbiology",topic:"Hepatitis",year:"Year 2",question:"Hepatitis B is transmitted PRIMARILY by:",options:["Faecal-oral route", "Blood sexual contact and vertical (mother-to-child) transmission", "Airborne droplets", "Contaminated food"],answer:1,explanation:"HBV is transmitted via infected blood, unprotected sex and vertically during childbirth."},
  {id:"mb007",subject:"Microbiology",topic:"Tuberculosis",year:"Year 2",question:"Tuberculosis is caused by:",options:["Mycobacterium leprae", "Mycobacterium tuberculosis", "Streptococcus pneumoniae", "Klebsiella pneumoniae"],answer:1,explanation:"Mycobacterium tuberculosis is an acid-fast bacillus (AFB) spread by respiratory droplets."},
  {id:"mb008",subject:"Microbiology",topic:"Fungi",year:"Year 1",question:"Candida albicans becomes pathogenic when:",options:["Exposed to sunlight", "Host immunity is compromised or normal flora disrupted", "Taken orally", "Exposed to antibiotics externally"],answer:1,explanation:"Candida is an opportunistic pathogen causing candidiasis when host defences are lowered."},
  {id:"mb009",subject:"Microbiology",topic:"Parasites",year:"Year 1",question:"The causative organism of malaria belongs to which genus?",options:["Leishmania", "Plasmodium", "Trypanosoma", "Giardia"],answer:1,explanation:"Malaria is caused by Plasmodium species; P. falciparum is the most lethal."},
  {id:"mb010",subject:"Microbiology",topic:"Infection Control",year:"Year 1",question:"Standard precautions apply to:",options:["HIV-positive patients only", "All patients regardless of diagnosis", "Known infectious patients", "Surgical patients only"],answer:1,explanation:"Standard precautions apply to ALL patients regardless of known or suspected infection status."},
  {id:"mb011",subject:"Microbiology",topic:"Bacteria",year:"Year 2",question:"Which organism is the most common cause of urinary tract infections (UTIs)?",options:["Staphylococcus aureus", "Escherichia coli", "Pseudomonas aeruginosa", "Klebsiella pneumoniae"],answer:1,explanation:"E. coli causes approximately 80% of community-acquired UTIs."},
  {id:"mb012",subject:"Microbiology",topic:"Hepatitis",year:"Year 1",question:"Hepatitis A is transmitted via:",options:["Blood and body fluids", "Faecal-oral route", "Sexual contact", "Respiratory droplets"],answer:1,explanation:"Hepatitis A is transmitted faecal-orally via contaminated food and water; it does not cause chronic infection."},
  {id:"mb013",subject:"Microbiology",topic:"Antibiotic Resistance",year:"Year 2",question:"MRSA stands for:",options:["Multi-resistant Staph aureus", "Methicillin-resistant Staphylococcus aureus", "Macrolide-resistant Strep aureus", "Multiple-resistant Streptococcal anaemia"],answer:1,explanation:"MRSA is resistant to all beta-lactam antibiotics due to the mecA gene encoding an altered PBP2a."},
  {id:"mb014",subject:"Microbiology",topic:"Sterilisation",year:"Year 1",question:"The MOST appropriate method for sterilising heat-sensitive instruments is:",options:["Autoclaving", "Dry heat oven", "Ethylene oxide gas sterilisation", "Boiling in water"],answer:2,explanation:"Ethylene oxide gas sterilisation works at low temperatures, suitable for heat-sensitive instruments."},
  {id:"mb015",subject:"Microbiology",topic:"Parasites",year:"Year 2",question:"Schistosomiasis is transmitted through:",options:["Mosquito bites", "Ingestion of contaminated water", "Skin penetration in fresh water containing cercariae", "Faecal-oral route"],answer:2,explanation:"Schistosomiasis: cercariae (released by freshwater snails) penetrate intact skin during water contact."},
  {id:"phc001",subject:"Primary Health Care",topic:"PHC Principles",year:"Year 1",question:"Which of the following is NOT one of the essential components of PHC?",options:["Health education", "Provision of essential medicines", "Specialist hospital care", "Safe water and sanitation"],answer:2,explanation:"PHC focuses on community-level care; specialist hospital care is secondary/tertiary, not a PHC component."},
  {id:"phc002",subject:"Primary Health Care",topic:"PHC Principles",year:"Year 1",question:"Community participation in PHC means:",options:["The government makes all health decisions", "Communities passively receive health services", "Communities actively involved in identifying needs and planning services", "Only professionals participate"],answer:2,explanation:"Community participation is a core PHC principle - communities have rights and responsibility in health care planning."},
  {id:"phc003",subject:"Primary Health Care",topic:"Health Promotion",year:"Year 1",question:"The Ottawa Charter (1986) first action area is:",options:["Develop personal skills", "Build healthy public policy", "Reorient health services", "Create supportive environments"],answer:1,explanation:"Ottawa Charter five action areas: Build healthy public policy, Create supportive environments, Strengthen community action, Develop personal skills, Reorient health services."},
  {id:"phc004",subject:"Primary Health Care",topic:"Levels of Care",year:"Year 1",question:"A general hospital is classified as which level of health care in Nigeria?",options:["Primary", "Secondary", "Tertiary", "Quaternary"],answer:1,explanation:"Nigeria 3-tier system: PHC = health posts/centres; Secondary = general hospitals (state); Tertiary = teaching hospitals (federal)."},
  {id:"phc005",subject:"Primary Health Care",topic:"Nutrition",year:"Year 1",question:"Kwashiorkor results from deficiency of:",options:["Calories only", "Protein (with adequate calories)", "Iron", "Vitamin A"],answer:1,explanation:"Kwashiorkor is protein-energy malnutrition with oedema and skin changes; marasmus is caloric deficiency."},
  {id:"phc006",subject:"Primary Health Care",topic:"Immunisation",year:"Year 1",question:"Oral Polio Vaccine (OPV) is given at birth and at what subsequent ages in Nigeria?",options:["1, 2, 3 months", "6, 10, 14 weeks", "6, 9, 12 months", "1, 3, 6 years"],answer:1,explanation:"Nigeria NPI schedule: OPV0 at birth, then OPV1/2/3 with pentavalent vaccine at 6, 10 and 14 weeks."},
  {id:"phc007",subject:"Primary Health Care",topic:"Nutrition",year:"Year 1",question:"Vitamin A deficiency leads to:",options:["Scurvy", "Night blindness and increased susceptibility to infection", "Rickets", "Beriberi"],answer:1,explanation:"Vitamin A deficiency causes night blindness, xerophthalmia and impaired immune function."},
  {id:"phc008",subject:"Primary Health Care",topic:"Malaria Control",year:"Year 2",question:"Long-lasting insecticidal nets (LLINs) prevent malaria by:",options:["Killing all mosquitoes in an area", "Creating a physical and chemical barrier against Anopheles mosquitoes", "Treating malaria after infection", "Providing herd immunity"],answer:1,explanation:"LLINs provide a physical barrier plus pyrethroid insecticide that kills or repels Anopheles mosquitoes."},
  {id:"phc009",subject:"Primary Health Care",topic:"TB Control",year:"Year 2",question:"DOTS (Directly Observed Treatment Short-course) for TB requires:",options:["Patient to self-administer treatment", "A trained observer watching each dose being taken", "Monthly clinic visits only", "Only injectable treatment"],answer:1,explanation:"DOTS: a trained person watches each patient swallow every dose to ensure adherence and prevent drug resistance."},
  {id:"phc010",subject:"Primary Health Care",topic:"HIV/AIDS",year:"Year 2",question:"PMTCT (Prevention of Mother-to-Child Transmission) of HIV involves:",options:["Caesarean section for all HIV+ mothers", "ART for mother during pregnancy/delivery and infant prophylaxis", "Formula feeding for all infants", "Avoiding all breastfeeding only"],answer:1,explanation:"PMTCT: ART for mother (to suppress viral load), infant ARV prophylaxis, and supported infant feeding decision."},
  {id:"phc011",subject:"Primary Health Care",topic:"Diarrhoea Control",year:"Year 1",question:"Oral Rehydration Therapy (ORT) works by:",options:["Killing diarrhoea-causing organisms", "Using glucose-facilitated sodium and water absorption in the gut", "Reducing gut motility", "Providing antibiotic treatment"],answer:1,explanation:"ORS uses the glucose-sodium co-transport mechanism to enhance sodium and water absorption, correcting dehydration."},
  {id:"phc012",subject:"Primary Health Care",topic:"Environmental Health",year:"Year 1",question:"The MOST cost-effective intervention to reduce diarrhoeal diseases is:",options:["Antibiotics", "Intravenous fluids", "Handwashing with soap", "Oral rehydration salts"],answer:2,explanation:"Handwashing with soap is the single most effective and cost-effective public health intervention for diarrhoeal diseases."},
  {id:"phc013",subject:"Primary Health Care",topic:"Nutrition",year:"Year 2",question:"A mid-upper arm circumference (MUAC) less than 11.5 cm in a child indicates:",options:["Normal nutrition", "Moderate acute malnutrition", "Severe acute malnutrition", "Overweight"],answer:2,explanation:"MUAC less than 11.5 cm = severe acute malnutrition; 11.5-12.5 cm = moderate; 12.5 cm or more = normal."},
  {id:"phc014",subject:"Primary Health Care",topic:"Health Indicators",year:"Year 2",question:"The Under-5 Mortality Rate (U5MR) is an important health indicator because it reflects:",options:["Adult health status", "Overall health and wellbeing of children and healthcare quality", "Economic productivity", "Maternal health only"],answer:1,explanation:"U5MR is a sensitive indicator of child survival, healthcare access, nutrition and overall health system performance."},
  {id:"phc015",subject:"Primary Health Care",topic:"PHC Principles",year:"Year 1",question:"Intersectoral collaboration in health means:",options:["Only health workers making decisions", "Cooperation between health and other sectors (agriculture education water)", "Hospitals working together", "International aid agencies collaborating"],answer:1,explanation:"Intersectoral collaboration recognises that health requires joint action across education, agriculture, housing and water sectors."},
  {id:"mh001",subject:"Mental Health Nursing",topic:"Mental Health Concepts",year:"Year 3",question:"According to WHO, mental health is:",options:["Having no diagnosable mental disorder", "A state of wellbeing where one realises their potential copes with stresses and contributes to community", "Taking no psychotropic medications", "Perfect cognitive function"],answer:1,explanation:"WHO defines mental health positively - not merely the absence of disorder but complete mental wellbeing."},
  {id:"mh002",subject:"Mental Health Nursing",topic:"Schizophrenia",year:"Year 3",question:"Positive symptoms of schizophrenia include all EXCEPT:",options:["Hallucinations", "Delusions", "Flat affect (blunted emotion)", "Disorganised speech"],answer:2,explanation:"Positive symptoms include hallucinations, delusions, disorganised speech. Flat affect is a negative symptom."},
  {id:"mh003",subject:"Mental Health Nursing",topic:"Depression",year:"Year 3",question:"A cardinal symptom of major depressive disorder is:",options:["Grandiosity", "Persistent low mood or loss of interest/pleasure (anhedonia)", "Flight of ideas", "Hallucinations"],answer:1,explanation:"Major depression: persistent depressed mood AND/OR loss of interest/pleasure for 2 or more weeks."},
  {id:"mh004",subject:"Mental Health Nursing",topic:"Bipolar Disorder",year:"Year 3",question:"During a manic episode, the nurse should prioritise:",options:["Stimulating the patient with activities", "Ensuring patient safety and reducing environmental stimulation", "Encouraging all spontaneous ideas", "Providing caffeine for alertness"],answer:1,explanation:"Manic patients have poor impulse control; safety and reducing stimulation are priorities."},
  {id:"mh005",subject:"Mental Health Nursing",topic:"Substance Abuse",year:"Year 3",question:"Delirium tremens (DTs) is a life-threatening complication of withdrawal from:",options:["Cannabis", "Opioids", "Alcohol", "Stimulants"],answer:2,explanation:"Alcohol withdrawal delirium (DTs) presents with tremors, agitation, hallucinations, seizures 24-72 hours after cessation."},
  {id:"mh006",subject:"Mental Health Nursing",topic:"Therapeutic Relationship",year:"Year 3",question:"The therapeutic relationship between nurse and patient should be:",options:["Social and friendship-based", "Professional with clear boundaries empathic and goal-directed", "Romantic and supportive", "Purely task-focused"],answer:1,explanation:"Therapeutic relationships are professional, boundaried, empathic, purposeful and patient-centred."},
  {id:"mh007",subject:"Mental Health Nursing",topic:"Anxiety Disorders",year:"Year 3",question:"In managing acute panic attacks, the nurse should first:",options:["Leave the patient alone", "Administer IV diazepam", "Stay with the patient and guide slow diaphragmatic breathing", "Restrain the patient"],answer:2,explanation:"For panic attacks: stay present, speak calmly, guide slow diaphragmatic breathing to reduce hyperventilation."},
  {id:"mh008",subject:"Mental Health Nursing",topic:"Psychotropic Drugs",year:"Year 3",question:"A patient on haloperidol develops muscle rigidity high fever and autonomic instability. This suggests:",options:["Tardive dyskinesia", "Neuroleptic Malignant Syndrome (NMS)", "Akathisia", "Dystonia"],answer:1,explanation:"NMS is a life-threatening reaction to antipsychotics: hyperthermia, muscle rigidity, altered consciousness. Stop drug immediately."},
  {id:"mh009",subject:"Mental Health Nursing",topic:"Mental Health Law",year:"Year 3",question:"Involuntary admission to a psychiatric facility is justified when a patient:",options:["Refuses all treatment", "Is an immediate danger to self or others and lacks insight", "Is chronically mentally ill", "Has a history of hospitalisation"],answer:1,explanation:"Involuntary admission is justified when the patient poses imminent danger AND lacks insight to consent to treatment."},
  {id:"mh010",subject:"Mental Health Nursing",topic:"Suicide Risk",year:"Year 3",question:"The HIGHEST risk factor for completed suicide is:",options:["Age under 25", "Being female", "Previous suicide attempt", "Social isolation"],answer:2,explanation:"The strongest predictor of completed suicide is a previous suicide attempt."},
  {id:"mh011",subject:"Mental Health Nursing",topic:"ECT",year:"Year 3",question:"ECT (electroconvulsive therapy) is commonly used for:",options:["Schizophrenia first-line", "Severe treatment-resistant depression", "Mild anxiety", "Dementia"],answer:1,explanation:"ECT is indicated for severe treatment-resistant depression, acute suicidality, severe mania or catatonia."},
  {id:"mh012",subject:"Mental Health Nursing",topic:"Communication",year:"Year 3",question:"When communicating with a patient experiencing delusions the nurse should:",options:["Argue and challenge the delusion directly", "Agree with the delusion to build rapport", "Neither reinforce nor directly challenge; focus on the patient's feelings", "Ignore the patient completely"],answer:2,explanation:"Do not reinforce delusions (agreeing) or directly challenge them; acknowledge feelings and redirect."},
  {id:"mh013",subject:"Mental Health Nursing",topic:"Community Mental Health",year:"Year 3",question:"Deinstitutionalisation in mental health refers to:",options:["Building more psychiatric hospitals", "Shifting care from large institutions to community-based services", "Banning all psychiatric treatment", "Compulsory hospitalisation for all patients"],answer:1,explanation:"Deinstitutionalisation shifts care from large inpatient institutions to community mental health centres."},
  {id:"mh014",subject:"Mental Health Nursing",topic:"Dementia",year:"Year 3",question:"The most common type of dementia is:",options:["Vascular dementia", "Lewy body dementia", "Frontotemporal dementia", "Alzheimer's disease"],answer:3,explanation:"Alzheimer's disease accounts for 60-70% of dementia cases; characterised by progressive memory loss."},
  {id:"mh015",subject:"Mental Health Nursing",topic:"Psychotropic Drugs",year:"Year 3",question:"Lithium toxicity is characterised by:",options:["Hypertension and tachycardia", "Coarse tremor ataxia confusion and renal failure at high levels", "Euphoria and increased energy", "Anorexia only"],answer:1,explanation:"Lithium toxicity (levels above 1.5 mEq/L): coarse tremor, nausea, ataxia, confusion; severe cases may need haemodialysis."},
  {id:"nd001",subject:"Nutrition & Dietetics",topic:"Macronutrients",year:"Year 1",question:"The primary role of carbohydrates in the body is:",options:["Building tissues", "Energy provision (4 kcal per gram)", "Hormone synthesis", "Oxygen transport"],answer:1,explanation:"Carbohydrates are the body's preferred energy source providing 4 kcal/gram; glucose is the primary brain fuel."},
  {id:"nd002",subject:"Nutrition & Dietetics",topic:"Macronutrients",year:"Year 1",question:"Which nutrient provides the highest caloric density?",options:["Carbohydrates (4 kcal/g)", "Proteins (4 kcal/g)", "Fats (9 kcal/g)", "Water (0 kcal/g)"],answer:2,explanation:"Fats provide 9 kcal per gram - more than double carbohydrates or proteins (4 kcal/g each)."},
  {id:"nd003",subject:"Nutrition & Dietetics",topic:"Vitamins",year:"Year 1",question:"Vitamin C deficiency causes:",options:["Rickets", "Scurvy", "Pellagra", "Beriberi"],answer:1,explanation:"Vitamin C deficiency causes scurvy: bleeding gums, perifollicular haemorrhages, impaired wound healing."},
  {id:"nd004",subject:"Nutrition & Dietetics",topic:"Vitamins",year:"Year 1",question:"Vitamin D is primarily synthesised by the body through:",options:["Dietary intake only", "Sunlight exposure (UV-B radiation)", "Intestinal bacteria", "Liver synthesis only"],answer:1,explanation:"UV-B radiation converts 7-dehydrocholesterol in the skin to previtamin D3, further converted in the liver and kidneys."},
  {id:"nd005",subject:"Nutrition & Dietetics",topic:"Therapeutic Diets",year:"Year 2",question:"A low-sodium diet is indicated for patients with:",options:["Hypocalcaemia", "Heart failure hypertension and renal disease", "Hypoglycaemia", "Anaemia"],answer:1,explanation:"Low-sodium diet reduces fluid retention and blood pressure; essential for heart failure, hypertension and renal disease."},
  {id:"nd006",subject:"Nutrition & Dietetics",topic:"Therapeutic Diets",year:"Year 2",question:"Patients with chronic renal failure are typically placed on a diet that is:",options:["High in protein and potassium", "Low in protein potassium and phosphorus", "High in sodium", "Unrestricted"],answer:1,explanation:"CRF: low protein (reduces urea), low potassium (prevents hyperkalaemia), low phosphorus (prevents renal bone disease)."},
  {id:"nd007",subject:"Nutrition & Dietetics",topic:"Malnutrition",year:"Year 1",question:"The difference between kwashiorkor and marasmus is:",options:["Kwashiorkor has no oedema; marasmus does", "Kwashiorkor has oedema (protein deficiency); marasmus is severe wasting (caloric deficiency)", "Both are the same condition", "Marasmus only affects adults"],answer:1,explanation:"Kwashiorkor = protein deficiency with oedema; Marasmus = total caloric starvation with severe wasting, no oedema."},
  {id:"nd008",subject:"Nutrition & Dietetics",topic:"Therapeutic Diets",year:"Year 2",question:"A diabetic diet should:",options:["Eliminate all carbohydrates", "Control carbohydrate intake and emphasise low glycaemic index foods", "Be high in saturated fat", "Include unlimited sugar"],answer:1,explanation:"Diabetic diet: controlled consistent carbohydrate intake with emphasis on complex low-GI carbohydrates."},
  {id:"nd009",subject:"Nutrition & Dietetics",topic:"Enteral Nutrition",year:"Year 2",question:"Nasogastric tube feeding is indicated when:",options:["The patient refuses food", "The GI tract is functional but the patient cannot take adequate oral nutrition", "Intravenous access is available", "The patient has severe diarrhoea"],answer:1,explanation:"Enteral feeding (NGT) is preferred when the gut is functional: 'if the gut works, use it'."},
  {id:"nd010",subject:"Nutrition & Dietetics",topic:"Breastfeeding",year:"Year 2",question:"Colostrum is especially important because it:",options:["Has fewer antibodies than mature milk", "Is high in IgA antibodies and growth factors providing passive immunity", "Has lower protein content", "Should be discarded"],answer:1,explanation:"Colostrum is rich in secretory IgA, lactoferrin, growth factors and leucocytes providing passive immune protection."},
  {id:"nd011",subject:"Nutrition & Dietetics",topic:"Minerals",year:"Year 1",question:"Iron deficiency is the most common cause of:",options:["Megaloblastic anaemia", "Microcytic hypochromic anaemia", "Haemolytic anaemia", "Aplastic anaemia"],answer:1,explanation:"Iron deficiency causes microcytic hypochromic anaemia due to reduced haemoglobin synthesis."},
  {id:"nd012",subject:"Nutrition & Dietetics",topic:"Vitamins",year:"Year 2",question:"Folic acid supplementation before and during early pregnancy prevents:",options:["Gestational diabetes", "Neural tube defects (spina bifida anencephaly)", "Pre-eclampsia", "Preterm labour"],answer:1,explanation:"Folic acid 400mcg/day taken before conception through 12 weeks reduces neural tube defects by up to 70%."},
  {id:"nd013",subject:"Nutrition & Dietetics",topic:"Obesity",year:"Year 2",question:"Body Mass Index (BMI) is calculated as:",options:["Height (m) / Weight (kg)", "Weight (kg) / Height squared (m2)", "Weight (kg) x Height (m)", "Weight (lb) / Height (in)"],answer:1,explanation:"BMI = weight in kg / height in m squared. Normal: 18.5-24.9; Overweight: 25-29.9; Obese: 30 or above."},
  {id:"nd014",subject:"Nutrition & Dietetics",topic:"Therapeutic Diets",year:"Year 2",question:"Coeliac disease requires strict avoidance of:",options:["Lactose", "Gluten (wheat barley rye)", "All fats", "Vitamin A"],answer:1,explanation:"Coeliac disease is an autoimmune reaction to gluten; strict lifelong gluten-free diet is the only effective treatment."},
  {id:"nd015",subject:"Nutrition & Dietetics",topic:"Therapeutic Diets",year:"Year 2",question:"A patient with hepatic encephalopathy needs a diet that is:",options:["High in protein to support liver repair", "Restricted in protein to reduce ammonia production", "High in fat", "Unrestricted in all nutrients"],answer:1,explanation:"In hepatic encephalopathy, protein is restricted to reduce ammonia production from gut bacteria."},
  {id:"me001",subject:"Medical Ethics & Law",topic:"Ethical Principles",year:"Year 1",question:"The four main bioethical principles (Beauchamp and Childress) are:",options:["Honesty compassion skill diligence", "Autonomy beneficence non-maleficence justice", "Consent confidentiality competence communication", "Equity access quality safety"],answer:1,explanation:"Beauchamp and Childress four principles: Autonomy, Beneficence (do good), Non-maleficence (do no harm), Justice."},
  {id:"me002",subject:"Medical Ethics & Law",topic:"Confidentiality",year:"Year 1",question:"Patient confidentiality may be broken when:",options:["A family member requests information", "The patient is admitted to hospital", "There is a serious risk of harm to a third party or the public", "The nurse thinks it is necessary"],answer:2,explanation:"Confidentiality can be breached when legally required (notifiable diseases) or there is serious imminent risk to third parties."},
  {id:"me003",subject:"Medical Ethics & Law",topic:"Consent",year:"Year 1",question:"A 15-year-old who fully understands a procedure may give consent under:",options:["Parent consent only", "Gillick competence if sufficiently mature to understand", "No circumstances until 18", "Written consent with two witnesses"],answer:1,explanation:"Gillick competence allows mature minors who fully understand the nature and consequences to give valid consent."},
  {id:"me004",subject:"Medical Ethics & Law",topic:"Negligence",year:"Year 2",question:"For a nurse to be found legally negligent it must be proven that:",options:["The patient was harmed by any means", "The nurse had a duty of care breached it and harm resulted", "The nurse made any error", "The hospital was understaffed"],answer:1,explanation:"The four elements of negligence: Duty of care existed, Duty was breached, Breach caused harm, Actual harm occurred."},
  {id:"me005",subject:"Medical Ethics & Law",topic:"Professional Standards",year:"Year 1",question:"The professional regulatory body for nurses in Nigeria is:",options:["Medical and Dental Council of Nigeria", "Nigerian Medical Association", "Nursing and Midwifery Council of Nigeria (NMCN)", "Federal Ministry of Health"],answer:2,explanation:"The NMCN is established by the Nursing and Midwifery Act to regulate nursing education, practice and conduct."},
  {id:"me006",subject:"Medical Ethics & Law",topic:"Patient Rights",year:"Year 2",question:"A patient's right to refuse treatment is an expression of which ethical principle?",options:["Beneficence", "Justice", "Autonomy", "Non-maleficence"],answer:2,explanation:"Patient autonomy is the right of competent patients to make decisions about their own healthcare."},
  {id:"me007",subject:"Medical Ethics & Law",topic:"Negligence",year:"Year 2",question:"Vicarious liability means:",options:["The nurse is personally liable for all errors", "An employer can be held liable for negligent acts of their employees in the course of employment", "Only doctors are liable", "Patients cannot sue nurses"],answer:1,explanation:"Vicarious liability makes employers (hospitals) legally responsible for the tortious acts of their employees."},
  {id:"me008",subject:"Medical Ethics & Law",topic:"End of Life",year:"Year 3",question:"Active euthanasia (deliberately causing death) is:",options:["Legal in most countries", "Illegal in Nigeria and most countries and contrary to nursing ethics", "Permitted in palliative care", "A nurse's prerogative"],answer:1,explanation:"Active euthanasia is illegal in Nigeria and most countries; it violates the principle of non-maleficence."},
  {id:"me009",subject:"Medical Ethics & Law",topic:"Professional Standards",year:"Year 1",question:"The ICN Code of Ethics outlines four fundamental nursing responsibilities as:",options:["Treat educate research administer", "Promote health prevent illness restore health alleviate suffering", "Diagnose treat refer discharge", "Assess plan implement evaluate"],answer:1,explanation:"ICN Code of Ethics: promoting health, preventing illness, restoring health and alleviating suffering."},
  {id:"me010",subject:"Medical Ethics & Law",topic:"Documentation",year:"Year 2",question:"Alteration of medical records is:",options:["Acceptable if done neatly", "Legal if the patient asks", "A serious professional and criminal offence", "Permitted for quality improvement"],answer:2,explanation:"Altering or falsifying medical records is professional misconduct and may constitute criminal fraud."},
  {id:"me011",subject:"Medical Ethics & Law",topic:"Whistleblowing",year:"Year 3",question:"A nurse who observes a colleague committing malpractice has a professional duty to:",options:["Ignore it to maintain team harmony", "Report it through appropriate channels (senior nurse management)", "Handle it personally without reporting", "Discuss it only with patients"],answer:1,explanation:"Nurses have a professional and ethical duty to report observed unsafe practice to protect patient safety."},
  {id:"me012",subject:"Medical Ethics & Law",topic:"Consent",year:"Year 1",question:"Implied consent is appropriate in which situation?",options:["Major elective surgery", "Unconscious emergency patient with life-threatening condition", "Routine blood tests", "HIV testing"],answer:1,explanation:"In emergencies where a patient is unconscious, implied consent assumes a rational person would consent to life-saving treatment."},
  {id:"me013",subject:"Medical Ethics & Law",topic:"Professional Standards",year:"Year 2",question:"A nurse's scope of practice is defined by:",options:["Personal skill and confidence", "The hospital administration only", "NMCN regulations professional standards and institutional policies", "Whatever the doctor orders"],answer:2,explanation:"Scope of practice is defined by NMCN, legislation, national standards, evidence-based guidelines and employer policies."},
  {id:"me014",subject:"Medical Ethics & Law",topic:"Research Ethics",year:"Year 2",question:"The Declaration of Helsinki governs:",options:["Patient discharge planning", "Ethics of human subjects research", "Nursing education standards", "Hospital accreditation"],answer:1,explanation:"The Declaration of Helsinki (1964, WMA) sets international ethical principles for medical research involving human subjects."},
  {id:"me015",subject:"Medical Ethics & Law",topic:"Patient Rights",year:"Year 2",question:"A patient with terminal cancer refuses further chemotherapy. The nurse should:",options:["Insist on treatment as it is the nurse's duty", "Inform the family and override the decision", "Respect the patient's decision and provide palliative care", "Seek legal injunction"],answer:2,explanation:"Competent patients have the right to refuse any treatment; the nurse must respect this and provide palliative care."},
  {id:"ed001",subject:"Emergency & Disaster Nursing",topic:"Triage",year:"Year 3",question:"In mass casualty triage, the GREEN tag indicates:",options:["Immediate life-threatening injuries", "Delayed - serious but not immediately life-threatening", "Minor injuries - walking wounded", "Expectant/unsalvageable"],answer:2,explanation:"Triage: RED = immediate; YELLOW = delayed; GREEN = minor (walking wounded); BLACK = expectant/dead."},
  {id:"ed002",subject:"Emergency & Disaster Nursing",topic:"CPR",year:"Year 3",question:"The recommended compression-to-ventilation ratio for adult CPR (single rescuer) is:",options:["15:2", "30:2", "5:1", "50:5"],answer:1,explanation:"AHA/ERC guidelines: 30 chest compressions to 2 rescue breaths (30:2) at a rate of 100-120 compressions/min."},
  {id:"ed003",subject:"Emergency & Disaster Nursing",topic:"ABCDE",year:"Year 3",question:"The ABCDE approach to emergency assessment stands for:",options:["Assess Breathe Circulate Diagnose Evaluate", "Airway Breathing Circulation Disability Exposure", "Alert Breathing Cardiac Dehydration Eliminate", "Airway Bleeding Circulation Deficiency Exposure"],answer:1,explanation:"ABCDE: Airway (with C-spine), Breathing, Circulation, Disability (neurological), Exposure."},
  {id:"ed004",subject:"Emergency & Disaster Nursing",topic:"Disaster Management",year:"Year 3",question:"The PRIMARY goal of disaster preparedness is:",options:["Political response", "Reducing morbidity mortality and suffering through planned response", "Media coverage", "Economic recovery only"],answer:1,explanation:"Disaster preparedness aims to minimise harm through advance planning, training, resource stockpiling and coordination."},
  {id:"ed005",subject:"Emergency & Disaster Nursing",topic:"Shock",year:"Year 3",question:"The EARLIEST sign of hypovolaemic shock is:",options:["Hypotension", "Bradycardia", "Tachycardia and anxiety", "Coma"],answer:2,explanation:"The earliest sign of hypovolaemia is tachycardia and anxiety (adrenergic response); hypotension is a late sign."},
  {id:"ed006",subject:"Emergency & Disaster Nursing",topic:"Poisoning",year:"Year 3",question:"Activated charcoal is used in poisoning management to:",options:["Induce vomiting", "Adsorb (bind) the ingested poison in the GI tract", "Neutralise acid ingestion", "Provide IV antidote"],answer:1,explanation:"Activated charcoal adsorbs many toxins in the gut, reducing systemic absorption; most effective within 1 hour."},
  {id:"ed007",subject:"Emergency & Disaster Nursing",topic:"Burns",year:"Year 3",question:"The first aid priority for chemical burns is:",options:["Applying a neutralising agent", "Immediate copious water irrigation for at least 20 minutes", "Covering with a dry dressing", "Applying ice packs"],answer:1,explanation:"Copious water irrigation (20-30 minutes) dilutes and removes the chemical; do NOT use neutralising agents."},
  {id:"ed008",subject:"Emergency & Disaster Nursing",topic:"Cardiac Emergencies",year:"Year 3",question:"An AED should be used on which cardiac rhythm?",options:["Asystole", "Pulseless electrical activity (PEA)", "Ventricular fibrillation (VF) and pulseless ventricular tachycardia", "Normal sinus rhythm"],answer:2,explanation:"AED (defibrillation) is indicated for shockable rhythms: VF and pulseless VT. Asystole and PEA are non-shockable."},
  {id:"ed009",subject:"Emergency & Disaster Nursing",topic:"Respiratory Emergencies",year:"Year 3",question:"Tension pneumothorax is characterised by:",options:["Bilateral lung collapse", "Tracheal deviation away from affected side absent breath sounds hypotension", "Mild chest pain only", "Crepitus at fracture site only"],answer:1,explanation:"Tension pneumothorax: tracheal deviation (away from affected side), absent breath sounds, distended neck veins, hypotension."},
  {id:"ed010",subject:"Emergency & Disaster Nursing",topic:"Disaster Management",year:"Year 3",question:"The Incident Command System (ICS) in disaster management provides:",options:["Medical treatment protocols", "A standardised all-hazard command structure for coordinating response", "Community early warning systems", "Hospital evacuation plans only"],answer:1,explanation:"ICS is a standardised management system providing a flexible scalable structure for multi-agency emergency responses."},
  {id:"mt001",subject:"Management & Teaching",topic:"Management Functions",year:"Year 3",question:"The four classic functions of management are:",options:["Leading motivating controlling hiring", "Planning organising directing/leading controlling", "Budgeting staffing evaluating training", "Assessment diagnosis implementation evaluation"],answer:1,explanation:"Classical management theory (Fayol): planning, organising, directing (leading), and controlling."},
  {id:"mt002",subject:"Management & Teaching",topic:"Leadership",year:"Year 3",question:"A democratic (participative) leadership style is best described as:",options:["Leader makes all decisions alone", "Leader consults team and involves them in decision-making", "Leader gives total freedom to staff", "Leader uses fear and punishment"],answer:1,explanation:"Democratic leadership involves team participation in decision-making; it improves job satisfaction and motivation."},
  {id:"mt003",subject:"Management & Teaching",topic:"Motivation",year:"Year 3",question:"Maslow's hierarchy applied to staff motivation suggests that:",options:["All staff are motivated only by salary", "Higher needs motivate once lower needs (physiological safety) are met", "Status is the only motivator", "All employees have the same motivational needs"],answer:1,explanation:"Managers must first ensure physiological needs and safety before higher motivators (recognition, growth) can be effective."},
  {id:"mt004",subject:"Management & Teaching",topic:"Quality Assurance",year:"Year 3",question:"Nursing audit is used to:",options:["Punish nurses for errors", "Evaluate nursing care against established standards to improve quality", "Monitor doctor performance", "Replace incident reporting"],answer:1,explanation:"Nursing audit systematically measures care delivery against professional standards, identifying gaps for improvement."},
  {id:"mt005",subject:"Management & Teaching",topic:"Delegation",year:"Year 3",question:"When delegating nursing tasks, the delegating nurse retains:",options:["No accountability", "Full accountability for the outcome", "Accountability only if the task fails", "Accountability for 24 hours only"],answer:1,explanation:"Delegation transfers the task but NOT the accountability; the delegating nurse remains accountable."},
  {id:"mt006",subject:"Management & Teaching",topic:"Teaching and Learning",year:"Year 3",question:"The cognitive domain of Bloom's taxonomy deals with:",options:["Attitudes and values", "Physical skills and motor tasks", "Knowledge and intellectual skills", "Emotional responses"],answer:2,explanation:"Bloom's taxonomy: Cognitive domain (knowledge, comprehension, application, analysis); Affective (attitudes); Psychomotor (skills)."},
  {id:"mt007",subject:"Management & Teaching",topic:"Teaching and Learning",year:"Year 3",question:"Return demonstration by a patient is the best method to evaluate learning in which domain?",options:["Cognitive", "Affective", "Psychomotor", "All three domains equally"],answer:2,explanation:"Return demonstration evaluates the psychomotor domain (practical skill performance)."},
  {id:"mt008",subject:"Management & Teaching",topic:"Conflict Management",year:"Year 3",question:"The win-win approach to conflict resolution is known as:",options:["Avoidance", "Accommodation", "Collaboration/problem-solving", "Competition"],answer:2,explanation:"Collaboration (problem-solving) seeks solutions satisfying all parties - a win-win approach."},
  {id:"mt009",subject:"Management & Teaching",topic:"Health Informatics",year:"Year 3",question:"Electronic health records (EHRs) in nursing improve patient care by:",options:["Replacing nurses", "Improving data access reducing errors and enhancing care coordination", "Creating additional workload with no benefit", "Replacing documentation entirely"],answer:1,explanation:"EHRs improve continuity of care, reduce medication errors, support clinical decision-making and enable audit."},
  {id:"mt010",subject:"Management & Teaching",topic:"Management Functions",year:"Year 3",question:"Management by Objectives (MBO) involves:",options:["Manager setting all objectives alone", "Setting specific measurable objectives collaboratively then evaluating performance against them", "Random performance evaluation", "No formal performance standards"],answer:1,explanation:"MBO (Drucker): managers and employees jointly set clear measurable objectives; performance evaluated against them."},
  {id:"rm001",subject:"Research Methodology",topic:"Research Design",year:"Year 2",question:"A randomised controlled trial (RCT) is classified as which type of study?",options:["Descriptive", "Qualitative", "Experimental", "Case study"],answer:2,explanation:"An RCT is the gold standard experimental design; participants are randomly allocated to intervention or control groups."},
  {id:"rm002",subject:"Research Methodology",topic:"Research Design",year:"Year 2",question:"In a cohort study, researchers follow a group of people:",options:["Retrospectively only", "Prospectively over time to observe outcomes", "Cross-sectionally at one point", "Using laboratory experiments"],answer:1,explanation:"Cohort studies follow exposed and unexposed groups prospectively over time to compare incidence of outcomes."},
  {id:"rm003",subject:"Research Methodology",topic:"Sampling",year:"Year 2",question:"Random sampling ensures:",options:["Every participant is interviewed", "Every member of the target population has an equal chance of being selected", "Only volunteers are selected", "The largest sample is chosen"],answer:1,explanation:"Random (probability) sampling gives every population member an equal independent chance of selection, reducing bias."},
  {id:"rm004",subject:"Research Methodology",topic:"Data Collection",year:"Year 2",question:"A Likert scale is used to measure:",options:["Height and weight", "Attitudes and opinions (degree of agreement)", "Blood pressure", "Bacterial colony counts"],answer:1,explanation:"Likert scales measure attitudes/opinions on an ordinal scale (Strongly agree to Strongly disagree)."},
  {id:"rm005",subject:"Research Methodology",topic:"Ethics in Research",year:"Year 2",question:"The Belmont Report principles governing research ethics include beneficence justice and:",options:["Competence", "Respect for persons (autonomy/informed consent)", "Confidentiality", "Accuracy"],answer:1,explanation:"Belmont Report (1979): Respect for Persons (autonomy, informed consent), Beneficence, Justice."},
  {id:"rm006",subject:"Research Methodology",topic:"Statistics",year:"Year 2",question:"The p-value in research indicates:",options:["The size of the effect", "The probability of obtaining the observed result if the null hypothesis were true", "The sample size needed", "The degree of correlation"],answer:1,explanation:"P-value = probability of results at least as extreme as observed, assuming the null hypothesis is true. P less than 0.05 = statistically significant."},
  {id:"rm007",subject:"Research Methodology",topic:"Research Design",year:"Year 2",question:"Qualitative research is best suited for:",options:["Counting and measuring outcomes", "Exploring experiences meanings and understanding of phenomena", "Establishing cause and effect", "Large population surveys"],answer:1,explanation:"Qualitative research explores how and why questions - understanding human experiences, perceptions and meanings."},
  {id:"rm008",subject:"Research Methodology",topic:"Literature Review",year:"Year 2",question:"A systematic review differs from a narrative review in that it:",options:["Uses any available sources", "Uses explicit reproducible methods to systematically search select and synthesise evidence", "Is written by one author", "Does not include statistical analysis"],answer:1,explanation:"Systematic reviews use pre-specified transparent methods to minimise bias in searching and appraising all evidence."},
  {id:"rm009",subject:"Research Methodology",topic:"Research Process",year:"Year 2",question:"The null hypothesis (H0) states that:",options:["There is a significant difference between groups", "There is no significant difference or relationship between variables", "The intervention will work", "The sample is biased"],answer:1,explanation:"H0 proposes no difference or association exists; research tests whether evidence is sufficient to reject H0."},
  {id:"rm010",subject:"Research Methodology",topic:"Evidence-Based Practice",year:"Year 3",question:"Evidence-based practice (EBP) in nursing integrates:",options:["Only research findings", "Best research evidence clinical expertise and patient preferences", "Doctor's orders only", "Tradition and custom"],answer:1,explanation:"EBP integrates: best available research evidence + clinician's expertise + patient's unique values and preferences."},
  {id:"psy001",subject:"Psychology",topic:"Personality Development",year:"Year 1",question:"According to Freud, the part of the personality that mediates between instinct and reality is the:",options:["Id", "Ego", "Superego", "Unconscious"],answer:1,explanation:"Freud's structural model: Id (instinctual drives), Ego (reality principle - mediates), Superego (moral conscience)."},
  {id:"psy002",subject:"Psychology",topic:"Defence Mechanisms",year:"Year 1",question:"A patient who is angry at a doctor but yells at a nurse is using the defence mechanism of:",options:["Projection", "Rationalisation", "Displacement", "Regression"],answer:2,explanation:"Displacement is redirecting emotions from the original source (doctor) to a safer substitute target (nurse)."},
  {id:"psy003",subject:"Psychology",topic:"Stress Response",year:"Year 1",question:"Selye's General Adaptation Syndrome (GAS) has three stages in order:",options:["Resistance alarm exhaustion", "Alarm resistance exhaustion", "Exhaustion alarm resistance", "Alarm exhaustion resistance"],answer:1,explanation:"GAS: (1) Alarm reaction (fight-or-flight), (2) Resistance (adaptation), (3) Exhaustion (resources depleted)."},
  {id:"psy004",subject:"Psychology",topic:"Grief",year:"Year 2",question:"Kubler-Ross's stages of grief are:",options:["Shock anger depression hope recovery", "Denial anger bargaining depression acceptance", "Confusion isolation anger depression hope", "Numbness pain adjustment acceptance growth"],answer:1,explanation:"Kubler-Ross (1969): Denial - Anger - Bargaining - Depression - Acceptance."},
  {id:"psy005",subject:"Psychology",topic:"Communication",year:"Year 1",question:"Non-verbal communication includes all EXCEPT:",options:["Eye contact", "Body posture", "Tone of voice", "The actual words spoken"],answer:3,explanation:"Non-verbal communication includes body language, facial expressions, eye contact, gestures, tone/pitch - not the words themselves."},
  {id:"psy006",subject:"Psychology",topic:"Developmental Psychology",year:"Year 1",question:"Erikson's psychosocial stage for an infant (0-18 months) is:",options:["Autonomy vs shame", "Initiative vs guilt", "Trust vs mistrust", "Industry vs inferiority"],answer:2,explanation:"Erikson's first stage: Trust vs. Mistrust (0-18 months) - consistent responsive caregiving fosters basic trust."},
  {id:"psy007",subject:"Psychology",topic:"Behaviour",year:"Year 2",question:"Classical conditioning was demonstrated by which psychologist?",options:["B.F. Skinner", "Carl Rogers", "Ivan Pavlov", "Abraham Maslow"],answer:2,explanation:"Ivan Pavlov demonstrated classical conditioning pairing a bell (neutral stimulus) with food to elicit salivation in dogs."},
  {id:"psy008",subject:"Psychology",topic:"Motivation",year:"Year 1",question:"Intrinsic motivation refers to motivation driven by:",options:["External rewards (money grades)", "Internal satisfaction interest and personal growth", "Fear of punishment", "Social pressure"],answer:1,explanation:"Intrinsic motivation comes from within - engaging for inherent satisfaction, curiosity or personal development."},
  {id:"soc001",subject:"Sociology",topic:"Social Concepts",year:"Year 1",question:"Parsons' sick role grants the right to be exempt from normal duties and the obligation to:",options:["Seek profit", "Seek professional help and work towards recovery", "Avoid all social contact", "Pay for healthcare"],answer:1,explanation:"Parsons' sick role: rights (exemption from duties, not blamed) + obligations (seek competent help, want to recover)."},
  {id:"soc002",subject:"Sociology",topic:"Social Class",year:"Year 1",question:"The social gradient of health refers to:",options:["People in higher social positions having worse health", "Higher social position being associated with better health outcomes", "Health being equal across all social classes", "Geography being the only determinant of health"],answer:1,explanation:"The social gradient: higher socioeconomic position is associated with progressively better health outcomes."},
  {id:"soc003",subject:"Sociology",topic:"Culture and Health",year:"Year 2",question:"Cultural competence in nursing means:",options:["Imposing Western health values on all patients", "Understanding and respecting patients cultural beliefs and practices in care", "Avoiding patients of different cultures", "Learning all languages"],answer:1,explanation:"Cultural competence involves understanding and respecting the cultural background, beliefs and practices of patients."},
  {id:"soc004",subject:"Sociology",topic:"Nigeria Health",year:"Year 2",question:"Nigeria's most common causes of preventable maternal death include:",options:["Hypertension alone", "Obstetric haemorrhage sepsis and hypertensive disorders", "Anaemia alone", "Malaria only"],answer:1,explanation:"Nigeria's maternal mortality is mainly due to obstetric haemorrhage, sepsis, obstructed labour and hypertensive disorders."},
  {id:"soc005",subject:"Sociology",topic:"Social Determinants",year:"Year 1",question:"Which is a SOCIAL determinant of health?",options:["Blood group", "Age and sex", "Education level and income", "Genetic inheritance"],answer:2,explanation:"Social determinants: the conditions in which people are born, live, work and age - education, income, employment, housing."},
  {id:"soc006",subject:"Sociology",topic:"Nigeria Health",year:"Year 2",question:"Nigeria's National Health Insurance Scheme (NHIS) was established to:",options:["Replace government hospitals", "Provide equitable access to healthcare through risk pooling", "Create private hospitals", "Finance medical school education"],answer:1,explanation:"NHIS aims to provide universal health coverage through prepayment and risk pooling."},
  {id:"soc007",subject:"Sociology",topic:"Gender and Health",year:"Year 1",question:"Gender-based violence (GBV) health consequences include:",options:["No health consequences", "Physical mental sexual and reproductive health consequences", "Only psychological consequences", "Only physical injuries"],answer:1,explanation:"GBV has wide-ranging consequences: physical injuries, mental health disorders, sexual/reproductive health problems."},
  {id:"soc008",subject:"Sociology",topic:"Health Behaviour",year:"Year 2",question:"The Health Belief Model predicts health action if the person perceives:",options:["Others doing the same", "Susceptibility to illness severity of illness and that benefits outweigh barriers", "Only that others expect it", "No barriers exist"],answer:1,explanation:"HBM: perceived susceptibility + severity = perceived threat; perceived benefits greater than barriers leads to action."},
  {id:"sc001",subject:"Applied Sciences",topic:"Physics",year:"Year 1",question:"Pascal's principle states that pressure applied to an enclosed fluid is:",options:["Reduced proportionally", "Transmitted equally in all directions", "Absorbed by the container", "Increased at depth only"],answer:1,explanation:"Pascal's principle: pressure applied to a confined fluid is transmitted undiminished in all directions."},
  {id:"sc002",subject:"Applied Sciences",topic:"Physics",year:"Year 1",question:"A sphygmomanometer measures blood pressure using the principle of:",options:["Gravity only", "External cuff pressure to occlude arterial blood flow", "Electrical resistance", "Doppler effect"],answer:1,explanation:"A sphygmomanometer applies external cuff pressure to compress the brachial artery; pressure is recorded when Korotkoff sounds appear and disappear."},
  {id:"sc003",subject:"Applied Sciences",topic:"Chemistry",year:"Year 1",question:"A pH of 7.35-7.45 represents:",options:["Acidic conditions", "Normal blood pH (slightly alkaline)", "Strongly alkaline", "Neutral only"],answer:1,explanation:"Normal arterial blood pH is 7.35-7.45 (slightly alkaline); below 7.35 = acidosis, above 7.45 = alkalosis."},
  {id:"sc004",subject:"Applied Sciences",topic:"Chemistry",year:"Year 1",question:"An electrolyte is a substance that:",options:["Does not dissolve in water", "Conducts electricity when dissolved in water by dissociating into ions", "Is always solid", "Cannot be given intravenously"],answer:1,explanation:"Electrolytes dissociate into cations and anions in water, essential for nerve conduction and muscle contraction."},
  {id:"sc005",subject:"Applied Sciences",topic:"Physics",year:"Year 1",question:"Osmosis is the movement of water across a semi-permeable membrane:",options:["From low to high solute concentration (high to low water concentration)", "From high to low solute concentration", "Against concentration gradient", "Requiring energy (active transport)"],answer:0,explanation:"Osmosis: water moves from low solute concentration (high water potential) to high solute concentration."},
  {id:"sc006",subject:"Applied Sciences",topic:"Chemistry",year:"Year 1",question:"Disinfectants differ from antiseptics in that disinfectants are used on:",options:["Living tissue only", "Inanimate surfaces/objects while antiseptics are used on living tissue", "Both living and non-living surfaces equally", "Internal body surfaces"],answer:1,explanation:"Disinfectants (e.g. bleach) kill microorganisms on inanimate surfaces; antiseptics (e.g. chlorhexidine) are safe for living tissue."},
  {id:"sc007",subject:"Applied Sciences",topic:"Physics",year:"Year 1",question:"X-rays used in medical imaging are a form of:",options:["Sound waves", "Electromagnetic radiation (high-energy ionising radiation)", "Magnetic fields", "Visible light"],answer:1,explanation:"X-rays are high-energy short-wavelength electromagnetic radiation that penetrate soft tissue to create medical images."},
  {id:"sc008",subject:"Applied Sciences",topic:"Chemistry",year:"Year 1",question:"The chemical formula for glucose (the main blood sugar) is:",options:["C6H12O6", "C12H22O11", "H2O", "CO2"],answer:0,explanation:"Glucose (a monosaccharide) has the molecular formula C6H12O6."},
  {id:"he001",subject:"Health Economics",topic:"Basic Concepts",year:"Year 3",question:"Opportunity cost in healthcare refers to:",options:["The price of a drug", "The value of the next best alternative foregone when a choice is made", "Administrative costs", "Staff salaries"],answer:1,explanation:"Opportunity cost = value of the best alternative given up when resources are allocated to another use."},
  {id:"he002",subject:"Health Economics",topic:"Health Financing",year:"Year 3",question:"User fees in healthcare create a barrier to access particularly for:",options:["Wealthy patients", "Low-income and vulnerable populations", "Health professionals", "Hospital administrators"],answer:1,explanation:"User fees create a financial barrier that disproportionately affects poor and vulnerable populations."},
  {id:"he003",subject:"Health Economics",topic:"GDP and Health",year:"Year 3",question:"The Abuja Declaration target requires African Union member states to allocate at least what percentage of national budgets to health?",options:["1-2%", "5%", "15%", "25%"],answer:2,explanation:"The 2001 Abuja Declaration committed African Union member states to allocate at least 15% of national budgets to health."},
  {id:"he004",subject:"Health Economics",topic:"Health Insurance",year:"Year 3",question:"Moral hazard in health insurance occurs when:",options:["Insurance companies defraud clients", "Insured individuals use more healthcare than they would if they bore the full cost", "Premiums are too high", "Providers refuse to treat insured patients"],answer:1,explanation:"Moral hazard: insured individuals may over-utilise services knowing the cost is covered."},
  {id:"he005",subject:"Health Economics",topic:"Cost Analysis",year:"Year 3",question:"Cost-effectiveness analysis (CEA) in healthcare measures outcomes in:",options:["Money (cost per naira spent)", "Natural health units (e.g. cost per life saved per case prevented)", "Quality-adjusted life years only", "Mortality rate reductions only"],answer:1,explanation:"CEA measures cost per unit of health outcome in natural units (e.g. cost per death averted, cost per case treated)."},
  {id:"he006",subject:"Health Economics",topic:"Nigeria Health System",year:"Year 3",question:"The NHIS in Nigeria primarily targets which population for coverage?",options:["Private sector employees only", "Federal government employees and their dependants (formal sector)", "Rural farmers only", "Children under 5 only"],answer:1,explanation:"NHIS initially covered federal government formal sector employees; coverage is expanding to include informal sector."},
  {id:"he007",subject:"Health Economics",topic:"Health Financing",year:"Year 3",question:"Out-of-pocket (OOP) healthcare payments in Nigeria account for approximately what percentage of total health expenditure?",options:["10-15%", "25-30%", "70-80%", "Less than 5%"],answer:2,explanation:"Nigeria has very high OOP payments (estimated 70-75% of total health expenditure), indicating low insurance coverage."},
  {id:"he008",subject:"Health Economics",topic:"Basic Concepts",year:"Year 3",question:"The demand for healthcare is described as 'derived demand' because:",options:["Patients enjoy consuming it", "Patients demand it not for its own sake but for the health it produces", "Doctors create all demand", "It is always inelastic"],answer:1,explanation:"Healthcare demand is derived: patients want health outcomes (wellness, pain relief), not healthcare services per se."},
];


const SUBJECTS = ['All', ...Array.from(new Set(questions.map(q => q.subject))).sort()];
const YEARS = ['All Years', 'Year 1', 'Year 2', 'Year 3'];

export default function PastQuestions() {
  const [selectedSubject, setSelectedSubject] = useState('All');
  const [selectedYear, setSelectedYear] = useState('All Years');
  const [answered, setAnswered] = useState<Record<string, number>>({});
  const [search, setSearch] = useState('');
  const [showExp, setShowExp] = useState<Record<string, boolean>>({});

  const filtered = questions.filter(q => {
    const mS = selectedSubject === 'All' || q.subject === selectedSubject;
    const mY = selectedYear === 'All Years' || q.year === selectedYear;
    const mQ = !search || q.question.toLowerCase().includes(search.toLowerCase()) || q.topic.toLowerCase().includes(search.toLowerCase()) || q.subject.toLowerCase().includes(search.toLowerCase());
    return mS && mY && mQ;
  });

  const totalAnswered = Object.keys(answered).length;
  const totalCorrect = Object.entries(answered).filter(([id, ans]) => {
    const q = questions.find(x => x.id === id);
    return q && q.answer === ans;
  }).length;

  const handleAnswer = (qid: string, idx: number) => {
    if (answered[qid] !== undefined) return;
    setAnswered(prev => ({ ...prev, [qid]: idx }));
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-10">
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white px-4 py-6">
        <div className="max-w-4xl mx-auto">
          <h1 className="text-2xl font-bold mb-1">Past Questions Bank</h1>
          <p className="text-blue-100 text-sm">NMCN General Nursing Programme — {questions.length} questions across all courses</p>
          {totalAnswered > 0 && (
            <div className="mt-3 bg-white/20 rounded-lg px-4 py-2 inline-flex items-center gap-4 text-sm flex-wrap">
              <span>Answered: <b>{totalAnswered}</b></span>
              <span>Correct: <b className="text-green-300">{totalCorrect}</b></span>
              <span>Score: <b>{Math.round((totalCorrect / totalAnswered) * 100)}%</b></span>
              <button onClick={() => { setAnswered({}); setShowExp({}); }} className="ml-2 bg-white/20 hover:bg-white/30 px-3 py-1 rounded text-xs">Reset All</button>
            </div>
          )}
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 mt-4 space-y-3">
        <input type="text" placeholder="Search questions, topics or subjects..." value={search} onChange={e => setSearch(e.target.value)} className="w-full border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"/>
        <div className="flex gap-2 flex-wrap items-center">
          <select value={selectedSubject} onChange={e => setSelectedSubject(e.target.value)} className="border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-500">
            {SUBJECTS.map(s => <option key={s} value={s}>{s === 'All' ? `All Subjects (${questions.length})` : `${s} (${questions.filter(q => q.subject === s).length})`}</option>)}
          </select>
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-500">
            {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <span className="text-sm text-gray-500">{filtered.length} question{filtered.length !== 1 ? 's' : ''} shown</span>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 mt-4 space-y-4">
        {filtered.map((q, idx) => {
          const userAnswer = answered[q.id];
          const isAnswered = userAnswer !== undefined;
          const isCorrect = isAnswered && userAnswer === q.answer;
          return (
            <div key={q.id} className="bg-white rounded-xl shadow-sm border border-gray-200 p-5">
              <div className="flex items-start justify-between mb-2 gap-2">
                <div className="flex gap-2 flex-wrap">
                  <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-medium">{q.subject}</span>
                  <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">{q.topic}</span>
                  <span className="text-xs bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-full">{q.year}</span>
                </div>
                <span className="text-xs text-gray-400 shrink-0">#{idx + 1}</span>
              </div>
              <p className="text-gray-800 font-medium mb-3 text-sm leading-relaxed">{q.question}</p>
              <div className="space-y-2">
                {q.options.map((opt, i) => {
                  let cls = "w-full text-left px-4 py-2.5 rounded-lg border text-sm transition-all ";
                  if (!isAnswered) cls += "border-gray-200 hover:border-blue-400 hover:bg-blue-50 cursor-pointer";
                  else if (i === q.answer) cls += "border-green-400 bg-green-50 text-green-800 font-medium";
                  else if (i === userAnswer) cls += "border-red-400 bg-red-50 text-red-700";
                  else cls += "border-gray-200 text-gray-400";
                  return (
                    <button key={i} className={cls} onClick={() => handleAnswer(q.id, i)}>
                      <span className="font-semibold mr-2">{String.fromCharCode(65 + i)}.</span>{opt}
                      {isAnswered && i === q.answer && <span className="ml-2">✓</span>}
                      {isAnswered && i === userAnswer && i !== q.answer && <span className="ml-2">✗</span>}
                    </button>
                  );
                })}
              </div>
              {isAnswered && (
                <div className="mt-3">
                  <button onClick={() => setShowExp(prev => ({ ...prev, [q.id]: !prev[q.id] }))} className="text-xs text-blue-600 hover:underline">
                    {showExp[q.id] ? 'Hide' : 'Show'} Explanation
                  </button>
                  {showExp[q.id] && (
                    <div className={`mt-2 text-sm px-4 py-3 rounded-lg ${isCorrect ? 'bg-green-50 text-green-800' : 'bg-orange-50 text-orange-800'}`}>
                      <b>{isCorrect ? '✓ Correct! ' : '✗ Incorrect. '}</b>{q.explanation}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
        {filtered.length === 0 && (
          <div className="text-center py-16 text-gray-400">
            <p className="text-4xl mb-3">📚</p>
            <p className="font-medium">No questions found</p>
            <p className="text-sm">Try adjusting your filters or search term</p>
          </div>
        )}
      </div>
    </div>
  );
}
